PAGE_MODULES.ai = [{"title": "眠宝关怀与咨询", "description": "显示小绵羊欢迎、四档今日感受、热门问题和自由咨询；支持本地关键词匹配、多意图合并与超范围回复。", "fields": "服务独立状态 mianbao-integrated-service-v1；sessions[]、messages[]、dailyCheckins[date]：mood、askedAt、answeredAt、deferred 等源模块字段。", "logic": "采用指定链接中的完整服务流程；会话超过 3 天未互动新建，历史保留近 12 个月；AI 为本地规则匹配，医学与政策内容待正式审核。该模块数据不改写首页、专病管理、权益中心与我的现有记录。"}, {"title": "创新支付、入组与援助申请", "description": "展示入组、福利订单和直付/后报销进度；在会话中逐步完善资料、上传材料、核对提交，支持暂停、恢复、重新填写及驳回补件。", "fields": "enrollment、type、code、patient、orders[]、aidDrafts 与会话 careFlows；材料图片本地保存。", "logic": "保留源模块的状态字典与订单过滤：20 区分药房审核阶段、21 过滤；后报销需处方与发票，直付含用药数量。申请提交为本地流程，未接保险/审核/理赔接口；不改变首页多元支付的状态。"}, {"title": "病历夹与用药记录", "description": "聊天中记录病程文字、录制语音、上传图片；支持时间线、类型筛选、音频回放、图片放大和用药记录。", "fields": "IndexedDB mianbao-integrated-care-records-v1 的 records、media；记录时间、文字、媒体、药品、用药状态、备注。", "logic": "语音为录音与回放，不含语音转文字；每段最长 2 分钟，图片每条最多 4 张，单文件最多 10 MB，图片压缩后保存。记录时间不能在未来，保存前需停止录音；用药状态含已服用/漏服/暂停，新增记录不提供医学建议。"}, {"title": "健康科普", "description": "先在聊天中展示三篇推荐文章；查看更多展开六篇文章及分类，支持全文阅读、收起与展开。", "fields": "源模块 articles[]、articleFilter、articleId 与消息 kind=articles/appPanel。", "logic": "所有文章操作保持在眠宝会话内；内容为记录与资料整理说明，正式医学内容和发布审核接口待接入。"}, {"title": "客服、不良事件与我的服务", "description": "真人客服入口、疑似不良事件识别与确认记录；头像展开患者资料、历史会话和福利关爱记录。", "fields": "patient、sessions[]、orders[]；历史会话分页；申请人姓名打码。reports[] 仅保留旧数据兼容，不新增事件记录。", "logic": "客服为源模块模拟服务，不实际拨号；不良事件仅本地记录，不能称为正式上报。历史会话、订单详情和材料查看均在当前会话中展开。"}, {"title": "会话快捷操作与状态设置", "description": "发起会话后，输入区上方展示可横向滑动的创新支付、记录病程、用药记录、真人客服；状态按钮保留源模块场景切换和数据重置。", "fields": "activeSession、view、conversationActions；入组/支付/订单状态控件。", "logic": "首屏与空会话不显示快捷按钮；状态设置只更新本服务模块。清空聊天保留说明、病历、用药与订单；重置仅清理本服务模块数据。宿主左侧说明及右侧修改意见沿用原保存机制。"}];

