PAGE_MODULES.home = [{"title": "首页滚动 Banner", "description": "首页标题下展示三张眠宝推荐卡片：健康记录、眠宝帮你、服务权益；可自动轮播、左右滑动、点击箭头或指示点切换。", "fields": "homeBanners[]：title、text、action、target、theme；homeBannerIndex、homeBannerPaused：当前会话状态。当前三项为可替换的静态配置。", "logic": "每 5 秒循环切换；点击按钮进入对应页面。离开首页清除计时器，返回重新启动；隐藏页面、焦点在轮播内、用户暂停或系统要求减少动态时不自动切换。切换仅更新轮播，不重绘页面或清空编辑内容。隐藏卡片不可获得焦点。业务活动图片、上线时间及运营配置接口待确认。"}, {"title": "状态打卡", "description": "四档状态选择：精神饱满/有些疲惫/需要小睡/状态不佳；\n选择后下方对应文案变更；", "fields": "moods[本地日期]：四档状态之一。\n建议正式字段（待确认）：userId、recordDate、moodCode、createdAt、updatedAt；recordDate 按选定业务时区生成。", "logic": "同日只能提交一次；已记录时禁用四个选项。\n\n【B02/B03｜现状】四档仅更新“今天的感受”文字；权益主文案由支付和服药记录决定。当前同日一次，不可修改。\n【建议规则（待确认）】晨起记录按 userId + recordDate 唯一；误选通过“修改当日状态”覆盖原记录而非新增，保留修改时间；未选择时显示引导，已选择时显示选中项。跨日重新计算日期及可选状态。\n【待确认】是否开放修改；四档对应反馈文案与形象配置；晨起反馈与权益信息的排列关系；日期统一北京时间还是用户时区。未确认前不把晨起状态当作疾病判断。"}, {"title": "眠宝权益卡", "description": "根据商保状态与今日用药记录展示对应文案；点击文案进入下一步，点击眠宝切换预览状态。", "fields": "当前字段补齐：insuranceStatus、meds[].day、homePreviewState。\n建议申请字段（待确认）：applicationId、applicationStatus、benefitStatus、updatedAt、rejectReason。", "logic": "未领取或审核中进入商保页；已领取未记录打开用药弹窗；已记录进入服药记录。\n\n【A02/D01｜现状】未领取/审核中进入 payment；已领取且今日无记录打开服药弹窗；已记录进入 med。点击眠宝可覆盖展示状态，不改变申请数据。\n【建议规则（待确认）】申请状态与权益可用状态分别保存；approved 只有经权益接口确认可用后才映射“已领取”。审核拒绝显示拒绝原因及重申入口，不能映射已领取。状态成功刷新后统一重算首页与支付详情。\n【待确认】未申请/审核中/已通过/已拒绝分别对应的首页文案、按钮、跳转；通过后是否需激活；多个申请取哪一份；申请服务、失效规则。临时展示状态不作为真实办理依据，正式版是否保留点击切换需确认。"}, {"title": "快捷服务", "description": "六个入口：药房地图、线上购药、多元支付、用药记录、不良反应速记和我的专员。", "fields": "pharmacy、shop、payment、medReminder、adverseForm、specialist。", "logic": "点击进入相应二级页面；首页不再展示随访管家和全部记录入口，我的页面的记录入口保持可用。"}, {"title": "今日用药与眠宝引导弹窗", "description": "点击今日用药或首页权益卡的记录按钮，居中弹出眠宝 GIF 引导；确认已按医嘱服药后保存，已记录时显示完成状态与查看入口。", "fields": "settings.medTime；meds[]：id、time、day、note；动效 assets/mianbao-med-guide.gif。", "logic": "点击任务不再直接跳详情；确认后保存当前时间与日期并关闭弹窗，同日该弹窗只保存一次，刷新任务及首页权益文案。已记录点击查看进入服药详情；开启减少动态时以静态眠宝替代 GIF。"}, {"title": "小憩引导弹窗与首页倒计时", "description": "点击日常小憩时钟居中弹出与今日用药同样的眠宝 GIF 卡片，填写时长并添加，随后关闭弹窗并在首页显示倒计时。进行中再次点击可暂停、继续或结束并记录。", "fields": "napSession：id、day、startedAt、totalSeconds、remainingSeconds、endsAt、status(running/paused/finished)；时长 1—120 整数分钟；naps[]：id、day、time、minutes；动效 assets/mianbao-nap-guide.gif。", "logic": "添加时建立计时会话，不计入已完成次数。倒计时每秒按 endsAt 和当前时间计算，不改写整页或左侧编辑内容；切换页面继续，刷新恢复。暂停保存剩余秒数，继续重建 endsAt。到时自动保存一条小憩记录，id 去重，归属开始日期；提前结束至少计时 1 秒才保存，分钟向上取整。保存失败保留会话可重试，不显示虚假完成；取消本次小憩不新增记录；未接入关闭页面后的通知。"}];
PAGE_MODULES.rights = [{"title": "创新支付状态与眠宝卡", "description": "顶部标题下展示眠宝形象、当前创新支付状态、状态说明和操作按钮；按钮进入商保直付页。", "fields": "当前读取 insuranceStatus：unclaimed → 未申请，reviewing → 审核中，claimed → 已通过，rejected → 已拒绝。当前本地流程只生成前三态，rejected 为兼容后续状态数据。\n正式申请来源、申请维度及审核接口仍待业务确认。", "logic": "【当前实现】进入权益中心实时读取状态；申请或权益状态变更后返回本页重算。未申请→了解申请流程；审核中→查看申请进度；已通过→查看用药权益；已拒绝→查看申请详情，均进入 payment。未知值回退为未申请。未接入真实审核，不生成虚构审核结果。\n【待确认】创新支付是否仅对应商保、通过与权益激活的关系、多份申请/拒绝原因/补件/撤回/重新申请/到期规则；正式状态以真实接口为准。"}, {"title": "商保直付入口", "description": "进入用药权益状态和申请流程页。", "fields": "目标页面 payment。\n建议 serviceCode、applicationId、currentApplication；权益卡与首页读取同一申请数据。", "logic": "首页权益卡同步读取该页的状态。\n\n【A02/D01｜建议规则（待确认）】进入商保直付查看本用户对应服务的当前申请；提交/状态更新后返回本页刷新卡片；无资格/服务不可用显示原因，不默认可申请。\n【待确认】资格核验、服务地区、创新支付卡是否汇总该入口、多个申请排序。"}, {"title": "商保计算器入口", "description": "进入费用与比例的预估计算页。", "fields": "目标页面 calculator。\n目标 calculator；预估规则包含 calculationVersion、serviceCode（若接入正式方案）。", "logic": "入口不直接计算或判断保险资格。\n\n【D02｜建议规则（待确认）】仅跳计算器；输入和结果不改变申请资格或审核状态；计算器明确金额性质和估算口径。\n【待确认】用户手填比例还是按方案计算、地区/保单数据来源。"}, {"title": "权益轮播 Banner（待实现）", "description": "最新意见要求自动滚动 Banner；本模块只补需求，当前中间页面不增加轮播。", "fields": "建议 bannerId、imageUrl、title、sortOrder、enabled、startAt、endAt、targetType、target、audienceRule。", "logic": "【A03｜建议规则（待确认）】仅展示已启用且在有效时间内的 Banner；按 sortOrder 排序；0 张隐藏区域，1 张不轮播，多张默认每 5 秒循环；支持手动切换，离开页面停止。点击按配置跳内部页面或受支持外链；无目标则不可点；图片失败使用占位，失效目标给出提示。\n【待确认】轮播间隔、尺寸/数量/指示器、配置来源、地区或状态定向、外链规则。"}];
