PAGE_MODULES.home = [{"title": "首次登录建档引导", "description": "手机号授权后到达首页，无健康档案时展示带眠宝的建档提示弹窗。", "fields": "onboardingPending、patientArchive；目标 patientArchive。", "logic": "点击建立档案进入两字段表单，稍后再说关闭提示；已有档案不展示。刷新时未处理的提示保留；不影响首页原任务与服务。"}, {"title": "眠宝权益卡", "description": "根据商保状态与今日用药记录展示对应文案；点击文案进入下一步，点击眠宝切换预览状态。", "fields": "当前字段补齐：insuranceStatus、meds[].day、homePreviewState。\n建议申请字段（待确认）：applicationId、applicationStatus、benefitStatus、updatedAt、rejectReason。", "logic": "未领取或审核中进入商保页；已领取未记录打开用药弹窗；已记录进入服药记录。\n\n【A02/D01｜现状】未领取/审核中进入 payment；已领取且今日无记录打开服药弹窗；已记录进入 med。点击眠宝可覆盖展示状态，不改变申请数据。\n【建议规则（待确认）】申请状态与权益可用状态分别保存；approved 只有经权益接口确认可用后才映射“已领取”。审核拒绝显示拒绝原因及重申入口，不能映射已领取。状态成功刷新后统一重算首页与支付详情。\n【待确认】未申请/审核中/已通过/已拒绝分别对应的首页文案、按钮、跳转；通过后是否需激活；多个申请取哪一份；申请服务、失效规则。临时展示状态不作为真实办理依据，正式版是否保留点击切换需确认。"}, {"title": "首页滚动 Banner", "description": "晨起状态与眠宝权益卡之后展示三张固定推荐卡片；支持自动轮播、箭头、指示点、横向滑动和暂停。", "fields": "homeBanners[]：title、text、action、target、theme；bannerStates.home：index、paused。", "logic": "页面顺序为顶部问候→晨起状态和眠宝权益卡→Banner→快捷服务→今日任务。轮播每 5 秒循环；离开页面清除计时器，页面隐藏、轮播内有焦点、主动暂停或系统要求减少动态时暂停。仅更新轮播区域，不清空左侧编辑输入。"}, {"title": "快捷服务", "description": "七个入口：病程记录、药房地图、线上购药、多元支付、用药记录、不良反应速记和我的专员。", "fields": "journey、pharmacy、shop、payment、medReminder、adverseForm、specialist。", "logic": "病程记录进入 journey 二级页，直接开始文字/图片/语音记录流程；其余入口保留原跳转。该页隐藏五项主导航，并通过顶部返回回到首页。不新增随访管家或全部记录入口。"}, {"title": "病程记录快捷入口", "description": "首页点病程记录后直接打开带眠宝的记录表单，可填写文字、上传图片、录制和回放语音。", "fields": "路由 journey；内嵌入口 entry=recordJourney。与眠宝帮您共用 IndexedDB mianbao-integrated-care-records-v1 的 records/media。", "logic": "文字≤2000 字；单条≤4 张图片、单张≤10 MB；单段录音≤2 分钟。文字、图片或语音至少一项；提交前停止录音并等待附件保存。保存到既有病历夹，同一来源可从眠宝帮您回看，不建立独立记录副本。"}, {"title": "今日用药与眠宝引导弹窗", "description": "点击今日用药或首页权益卡的记录按钮，居中弹出眠宝 GIF 引导；确认已按医嘱服药后保存，已记录时显示完成状态与查看入口。", "fields": "settings.medTime；meds[]：id、time、day、note；动效 assets/mianbao-med-guide.gif。", "logic": "点击任务不再直接跳详情；确认后保存当前时间与日期并关闭弹窗，同日该弹窗只保存一次，刷新任务及首页权益文案。已记录点击查看进入服药详情；开启减少动态时以静态眠宝替代 GIF。"}, {"title": "小憩引导弹窗与首页倒计时", "description": "点击日常小憩时钟居中弹出与今日用药同样的眠宝 GIF 卡片，填写时长并添加，随后关闭弹窗并在首页显示倒计时。进行中再次点击可暂停、继续或结束并记录。", "fields": "napSession：id、day、startedAt、totalSeconds、remainingSeconds、endsAt、status(running/paused/finished)；时长 1—120 整数分钟；naps[]：id、day、time、minutes；动效 assets/mianbao-nap-guide.gif。", "logic": "添加时建立计时会话，不计入已完成次数。倒计时每秒按 endsAt 和当前时间计算，不改写整页或左侧编辑内容；切换页面继续，刷新恢复。暂停保存剩余秒数，继续重建 endsAt。到时自动保存一条小憩记录，id 去重，归属开始日期；提前结束至少计时 1 秒才保存，分钟向上取整。保存失败保留会话可重试，不显示虚假完成；取消本次小憩不新增记录；未接入关闭页面后的通知。"}, {"title": "状态打卡", "description": "四档状态选择：精神饱满/有些疲惫/需要小睡/状态不佳；\n选择后下方对应文案变更；", "fields": "moods[本地日期]：四档状态之一。\n建议正式字段（待确认）：userId、recordDate、moodCode、createdAt、updatedAt；recordDate 按选定业务时区生成。", "logic": "同日只能提交一次；已记录时禁用四个选项。\n\n【B02/B03｜现状】四档仅更新“今天的感受”文字；权益主文案由支付和服药记录决定。当前同日一次，不可修改。\n【建议规则（待确认）】晨起记录按 userId + recordDate 唯一；误选通过“修改当日状态”覆盖原记录而非新增，保留修改时间；未选择时显示引导，已选择时显示选中项。跨日重新计算日期及可选状态。\n【待确认】是否开放修改；四档对应反馈文案与形象配置；晨起反馈与权益信息的排列关系；日期统一北京时间还是用户时区。未确认前不把晨起状态当作疾病判断。"}];
PAGE_MODULES.special = [{"title": "本月与今日记录", "description": "一张卡片展示本月及今日猝倒记录次数、眠宝反馈和快速记录按钮。", "fields": "events[].day、本月与上月事件数、今日事件数。\n建议统计参数：periodStart、periodEnd、comparisonStart、comparisonEnd、count、comparisonCount、hasRecordedData。", "logic": "月度反馈按已记录次数比较；快速记录保存后同时更新月度和今日统计。\n\n【C03｜现状】本月累计条数直接与上个完整月比较；上月 0 条进入无上月记录文案。统计是已记录次数，不是完整发作次数。\n【建议规则（待确认）】默认对比同等经过天数；展示两个区间及记录次数，用“记录增加/减少/持平”文案。无记录标“无已记录数据”，不推断没有事件。补录、编辑、删除后重算对应日/月，并清除临时展示覆盖态。\n【待确认】等长区间或整月比较、2 月与大小月截止处理、是否要明确记录“无事件”、月度提示文案。正式版不以记录减少直接得出病情改善。"}, {"title": "猝倒周期趋势", "description": "按周展示每日猝倒次数，支持前后切周与查看所选周记录。", "fields": "weekOffset、events[].day。\n建议趋势字段：periodStart、periodEnd、dayCounts[]、selectedWeek；条目按 occurredAt 过滤。", "logic": "周一至周日聚合；查看记录从底部弹出所选周列表。\n\n【C04｜现状】周图与底部列表按同一 weekOffset/日期过滤；图表无记录画为 0。\n【建议规则（待确认）】周一至周日，同一周范围同时驱动图表与列表；允许历史周，不允许超过当前周；返回时保留选中周。新增/修改/删除后更新受影响周；无数据显示“该周暂无已记录事件”。\n【待确认】最早查询范围、无记录日是否用空标记、是否加入月份/诱因分析。独立 trend 页的入口和保留范围另行确认。"}, {"title": "测评记录", "description": "显示 ESS 量表和 SRSS 量表名称；下方卡片可左右滑动，支持点击量表名称、箭头或键盘方向键切换。", "fields": "scaleCatalog[]：code、name、canAnswer；activeScale；ess[]；scalePhotos[]；scrollLeft 为卡片视图位置。", "logic": "当前量表清单为 ESS、SRSS。名称高亮与当前卡片同步；第一张禁止向前、最后一张禁止向后，不循环。ESS 支持答题/拍照，SRSS 支持拍照；拍照按钮携带对应 scale，不依赖之前打开过哪张卡。切卡只更新选中视图，不重绘页面，不清空左侧编辑内容。趋势沿用现有本周得分计算；正式量表清单、版本、计分及医学审核仍待接入。"}, {"title": "睡眠辅助工具", "description": "按小憩闹钟、注意力挑战、睡眠日志的顺序展示三个入口。", "fields": "nap、game、sleepList。", "logic": "该区域仅展示小憩闹钟、注意力挑战、睡眠日志三个入口，分别进入 nap、game、sleepList；返回后沿用原记录。科学小贴士不在本区域展示，不良反应速记已按此前要求移除。“睡眠日子”按睡眠日志处理。"}, {"title": "健康档案导航与页面命名", "description": "底部专病管理改为健康档案；左侧分组同步显示健康档案。", "fields": "Tab label=健康档案；route=special；专区页面标题仍为发作性睡病专区。", "logic": "只修改导航和分组名称，保留原路由、页面功能及记录关联，不重建记录。二级页面不展示主导航。"}];
PAGE_MODULES.rights = [{"title": "权益轮播 Banner", "description": "权益中心标题下展示自动滚动的眠宝 Banner，随后是创新支付状态卡，再下方为多元支付与保障。", "fields": "rightsBanners[]：title、text、action、target、theme；bannerStates.rights：index、paused。", "logic": "三张固定卡片进入商保直付、商保计算器、眠宝帮您；每 5 秒轮播，可手动切换或暂停。权益与首页独立保存会话索引和暂停状态；隐藏页面、焦点在轮播内或减少动态时暂停。离开页面停止计时，返回恢复所选卡。"}, {"title": "创新支付状态与眠宝卡", "description": "在 Banner 与多元支付与保障之间展示带眠宝的创新支付状态卡，概览名称仅为未申请、审核中、已申请。", "fields": "insuranceStatus；paymentSummary() 输出 key=unclaimed/reviewing/applied；label、copy、action。", "logic": "按本次确认保留文档三种概览名称。原型临时将旧 claimed/rejected 展示归入 applied，保留其底层数据，不表示两种审核结果业务等价。已申请的正式含义及真实状态映射另行定义；卡片不宣称通过、领取、支付或履约完成。三个按钮均进入原申请详情服务，正式统一数据与接口仍待实现。"}, {"title": "商保直付入口", "description": "进入用药权益状态和申请流程页。", "fields": "目标页面 payment。\n建议 serviceCode、applicationId、currentApplication；权益卡与首页读取同一申请数据。", "logic": "首页权益卡同步读取该页的状态。\n\n【A02/D01｜建议规则（待确认）】进入商保直付查看本用户对应服务的当前申请；提交/状态更新后返回本页刷新卡片；无资格/服务不可用显示原因，不默认可申请。\n【待确认】资格核验、服务地区、创新支付卡是否汇总该入口、多个申请排序。"}, {"title": "商保计算器入口", "description": "进入费用与比例的预估计算页。", "fields": "目标页面 calculator。\n目标 calculator；预估规则包含 calculationVersion、serviceCode（若接入正式方案）。", "logic": "入口不直接计算或判断保险资格。\n\n【D02｜建议规则（待确认）】仅跳计算器；输入和结果不改变申请资格或审核状态；计算器明确金额性质和估算口径。\n【待确认】用户手填比例还是按方案计算、地区/保单数据来源。"}];
PAGE_MODULES.journey = [{"title": "记录内容与时间", "description": "带眠宝的病程记录卡片；默认当前时间，可改时间并填写文字。", "fields": "records：id、type=journey、when、created、updated、flowId、title、text、media[]；文字≤2000 字。", "logic": "文字、图片或语音至少一项；时间需有效，现有实现允许约 1 分钟的时钟误差。保存失败保留输入可重试，不提供诊断或处方建议。"}, {"title": "图片与语音附件", "description": "支持上传图片、录音、停止、回放和图片预览。", "fields": "media：id、blob；记录引用 id/kind/name/duration；最多 4 张图，单图≤10 MB，压缩最长边约1600px；录音≤2分钟。", "logic": "录音需麦克风权限；不支持、未授权或设备错误时使用文字/图片。录音中或处理附件时禁止提交；语音保存原音频，不自动转写。附件与记录共用眠宝 IndexedDB。"}, {"title": "保存与回顾", "description": "保存后显示成功，并提供打开病历夹入口；顶部可返回首页。", "fields": "与眠宝帮您共用 records/media 和会话存储，entry=recordJourney 直接启动记录流程。", "logic": "不创建第二套数据；可从病历夹查看、回放或修改既有记录。二级页隐藏主导航，返回首页保留已保存内容。"}];

