PAGE_MODULES.home = [{"title": "首次登录建档引导", "description": "手机号授权后到达首页，无健康档案时展示带眠宝的建档提示弹窗。", "fields": "onboardingPending、patientArchive；目标 patientArchive。", "logic": "点击建立档案进入两字段表单，稍后再说关闭提示；已有档案不展示。刷新时未处理的提示保留；不影响首页原任务与服务。"}, {"title": "眠宝权益卡", "description": "根据商保状态与今日用药记录展示对应文案；点击文案进入下一步，点击眠宝切换预览状态。", "fields": "当前字段补齐：insuranceStatus、meds[].day、homePreviewState。\n建议申请字段（待确认）：applicationId、applicationStatus、benefitStatus、updatedAt、rejectReason。", "logic": "未领取或审核中进入商保页；已领取未记录打开用药弹窗；已记录进入服药记录。\n\n【A02/D01｜现状】未领取/审核中进入 payment；已领取且今日无记录打开服药弹窗；已记录进入 med。点击眠宝可覆盖展示状态，不改变申请数据。\n【建议规则（待确认）】申请状态与权益可用状态分别保存；approved 只有经权益接口确认可用后才映射“已领取”。审核拒绝显示拒绝原因及重申入口，不能映射已领取。状态成功刷新后统一重算首页与支付详情。\n【待确认】未申请/审核中/已通过/已拒绝分别对应的首页文案、按钮、跳转；通过后是否需激活；多个申请取哪一份；申请服务、失效规则。临时展示状态不作为真实办理依据，正式版是否保留点击切换需确认。"}, {"title": "首页滚动 Banner", "description": "晨起状态与眠宝权益卡之后展示三张固定推荐卡片；支持自动轮播、箭头、指示点、横向滑动和暂停。", "fields": "homeBanners[]：title、text、action、target、theme；bannerStates.home：index、paused。", "logic": "页面顺序为顶部问候→晨起状态和眠宝权益卡→Banner→快捷服务→今日任务。轮播每 5 秒循环；离开页面清除计时器，页面隐藏、轮播内有焦点、主动暂停或系统要求减少动态时暂停。仅更新轮播区域，不清空左侧编辑输入。"}, {"title": "快捷服务", "description": "八个入口：语音病历、病程记录、药房地图、线上购药、多元支付、用药记录、不良反应速记和我的专员。", "fields": "voiceCase、journey、pharmacy、shop、payment、medReminder、adverseForm、specialist。", "logic": "语音病历进入 voiceCase 独立二级页；病程记录进入既有 journey 文字/图片/录音流程；其余入口保留原跳转。所有二级页面隐藏五项主导航，并通过顶部返回回到首页。"}, {"title": "语音病历快捷入口", "description": "点击语音病历进入独立二级页面，由眠宝引导讲述时间、症状和次数。", "fields": "route=voiceCase；historyRoute=voiceCaseHistory；state.voiceCases[]。", "logic": "本次按用户确认仅实现 Demo 展示。点击或长按底部按钮展示固定示例整理效果；不调用麦克风、语音转写或真实大模型。该二级页不展示首页功能栏。"}, {"title": "病程记录快捷入口", "description": "首页点病程记录后直接打开带眠宝的记录表单，可填写文字、上传图片、录制和回放语音。", "fields": "路由 journey；内嵌入口 entry=recordJourney。与眠宝帮您共用 IndexedDB mianbao-integrated-care-records-v1 的 records/media。", "logic": "文字≤2000 字；单条≤4 张图片、单张≤10 MB；单段录音≤2 分钟。文字、图片或语音至少一项；提交前停止录音并等待附件保存。保存到既有病历夹，同一来源可从眠宝帮您回看，不建立独立记录副本。"}, {"title": "今日用药与眠宝引导弹窗", "description": "点击今日用药或首页权益卡的记录按钮，居中弹出眠宝 GIF 引导；确认已按医嘱服药后保存，已记录时显示完成状态与查看入口。", "fields": "settings.medTime；meds[]：id、time、day、note；动效 assets/mianbao-med-guide.gif。", "logic": "点击任务不再直接跳详情；确认后保存当前时间与日期并关闭弹窗，同日该弹窗只保存一次，刷新任务及首页权益文案。已记录点击查看进入服药详情；开启减少动态时以静态眠宝替代 GIF。"}, {"title": "小憩引导弹窗与首页倒计时", "description": "点击日常小憩时钟居中弹出与今日用药同样的眠宝 GIF 卡片，填写时长并添加，随后关闭弹窗并在首页显示倒计时。进行中再次点击可暂停、继续或结束并记录。", "fields": "napSession：id、day、startedAt、totalSeconds、remainingSeconds、endsAt、status(running/paused/finished)；时长 1—120 整数分钟；naps[]：id、day、time、minutes；动效 assets/mianbao-nap-guide.gif。", "logic": "添加时建立计时会话，不计入已完成次数。倒计时每秒按 endsAt 和当前时间计算，不改写整页或左侧编辑内容；切换页面继续，刷新恢复。暂停保存剩余秒数，继续重建 endsAt。到时自动保存一条小憩记录，id 去重，归属开始日期；提前结束至少计时 1 秒才保存，分钟向上取整。保存失败保留会话可重试，不显示虚假完成；取消本次小憩不新增记录；未接入关闭页面后的通知。"}, {"title": "状态打卡", "description": "四档状态选择：精神饱满/有些疲惫/需要小睡/状态不佳；\n选择后下方对应文案变更；", "fields": "moods[本地日期]：四档状态之一。\n建议正式字段（待确认）：userId、recordDate、moodCode、createdAt、updatedAt；recordDate 按选定业务时区生成。", "logic": "同日只能提交一次；已记录时禁用四个选项。\n\n【B02/B03｜现状】四档仅更新“今天的感受”文字；权益主文案由支付和服药记录决定。当前同日一次，不可修改。\n【建议规则（待确认）】晨起记录按 userId + recordDate 唯一；误选通过“修改当日状态”覆盖原记录而非新增，保留修改时间；未选择时显示引导，已选择时显示选中项。跨日重新计算日期及可选状态。\n【待确认】是否开放修改；四档对应反馈文案与形象配置；晨起反馈与权益信息的排列关系；日期统一北京时间还是用户时区。未确认前不把晨起状态当作疾病判断。"}];
PAGE_MODULES.records = [{"title": "记录分类", "description": "语音病历、服药、猝倒、睡眠、ESS 和不良反应六类入口。", "fields": "voiceCases、meds、events、sleep、ess、adverse 的数组长度及对应记录路由。", "logic": "数量按数组长度实时计算。\n\n【C10｜现状】仅五类，不含小憩、照片/SRSS、游戏、预约与晨起状态。\n【建议规则（待确认）】用一份类别配置供“我的记录/全部记录”；展示每类有效记录全量条数，不含草稿/失败；测评按记录统一列表，明确有分数与无分数照片是否计数。\n【待确认】本期类别清单；未纳入类型是否有其他全量入口；重复来源与任务计数不能混用。"}, {"title": "分类跳转", "description": "点击分类进入对应记录列表。", "fields": "目标页面。\n建议 target、filters、pageCursor、returnTarget；所有私有数据绑定 userId。", "logic": "语音病历进入 voiceCaseHistory；其余分类保留原对应列表。各类条数读取已保存数据，不统计未保存草稿。"}];
PAGE_MODULES.voiceCase = [{"title": "页面导航与眠宝引导", "description": "顶部返回、语音病历标题、查看记录入口；中间展示眠宝和讲述示例。", "fields": "route=voiceCase；route.caseId：可选历史记录 ID。", "logic": "从首页进入新建；从记录列表携带 caseId 打开已保存内容。不存在的 ID 回退到新建。二级页隐藏主导航，底部录入按钮固定，结果区域独立滚动。"}, {"title": "底部语音按钮与整理状态", "description": "支持点击和长按，展示聆听、整理中及结果回显。", "fields": "临时 voiceCaseUi：phase=idle/listening/processing/ready、referenceAt、draft、savedId、job、timer。", "logic": "Demo 使用固定原话，不采集真实音频、不接真实转写或大模型。按下记录 referenceAt，松开后整理；点击直接体验同一效果。整理中禁用录入；触摸取消或 Escape 取消当前聆听。离开页面取消未完成任务，避免延迟结果覆盖其他页面；未保存草稿离开后不保留。键盘空格/回车可触发。"}, {"title": "原始描述与整理病历", "description": "分卡展示完整原话和整理后的描述，时间、症状、次数标红。", "fields": "originalText、optimizedText、highlights[]：field(time/symptoms/count)、text；source=demo。", "logic": "仅整理示例原意，不新增疾病诊断，不将“大概三次”改为精确次数。普通文字不标红；关键字段按结构化 highlights 渲染且转义文本。固定示例：昨天晚上看电视、大笑后双腿发软和站立不稳、大概三次。"}, {"title": "时间转换与症状次数字段", "description": "时间显示原始描述和具体日期；症状显示原始描述和提取内容；次数只显示原始描述。", "fields": "time.originalDescription、time.convertedDate(YYYY-MM-DD)；symptoms.originalDescription、symptoms.extracted；count.originalDescription；referenceAt(ISO)、timeZone=Asia/Shanghai。", "logic": "“昨天晚上”以按下按钮时的北京时间业务日期减一天；保留晚间描述，不编造具体时分。日期转换以该条记录的 referenceAt 为锚点，次日回看不重新计算。症状保留原话并归纳为“双腿发软、站立不稳”；次数保存“大概出现了三次”，本期不增加数值次数字段。"}, {"title": "保存病历与记录回看", "description": "结果底部显示保存病历；成功后显示已保存，顶部可进入语音病历记录列表。", "fields": "state.voiceCases[]：id、createdAt、updatedAt、source、referenceAt、timeZone、originalText、optimizedText、highlights、time、symptoms、count；浏览器存储键 mianbao-prototype-v1。", "logic": "仅 ready 且有 draft 时允许保存。单次结果只保存一次，重复操作不新增；再记录形成新结果。保存失败恢复原数组并保留草稿，可重试。语音病历独立保存结构化结果，不自动新增猝倒记录、不改动病程记录/用药统计。与主应用同一存储键，清除主应用记录时一并清理；账号与云同步未接入。"}];
