PAGE_MODULES.rights = [{"title": "知识中心导航与眠宝引导", "description": "页面标题及底部导航显示知识中心，顶部以医生形象眠宝引导阅读。", "fields": "导航 label=知识中心；route=rights（保留原路由键）；首页 homeBanners[2].target=rights。", "logic": "权益中心页面整体替换为知识中心，不展示创新支付状态卡、保障服务卡或 Banner。首页多元支付及眠宝帮您中已有申请功能保留；标题更名不改变支付数据。"}, {"title": "文章分类筛选", "description": "显示全部、就医准备、日常记录、用药记录、援助服务分类，可横向滚动。", "fields": "knowledgeCategories 由文章分类去重；knowledgeFilter；knowledgeArticles[].category。", "logic": "默认全部，点击分类只更新筛选按钮和文章列表，不重绘整页或清空左侧编辑内容；分类及列表位置在当前会话保留，刷新回到全部。"}, {"title": "患教文章列表", "description": "显示文章分类、预计阅读时长、标题和摘要，点击整张文章卡片阅读。", "fields": "knowledgeArticles[]：id、category、title、summary、read、icon、theme、sections[][]；当前 6 篇本地文章。", "logic": "按配置顺序展示，分类过滤与篇数使用同一结果；无匹配时显示空列表提示。正文复用既有眠宝模块中的记录与资料整理内容，暂不接文章管理后台。"}, {"title": "详情跳转与回到列表", "description": "点击文章以唯一 ID 进入文章详情，返回列表可继续浏览。", "fields": "route=articleDetail；route.articleId；knowledgeScrollTop。", "logic": "进入详情前保存列表滚动位置；返回读取同一目录并恢复当前分类和位置，不创建新会话或患者记录。详情为二级页，隐藏首页功能栏。"}];
PAGE_MODULES.articleDetail = [{"title": "文章基本信息", "description": "显示分类、预计阅读时长、标题和摘要。", "fields": "route.articleId；article.id、category、read、title、summary。", "logic": "以 articleId 查找文章；不编造作者、发布日期或审核信息。无法查到时提示文章暂不可用，提供返回知识中心入口。"}, {"title": "文章正文", "description": "按段落展示小标题和正文，底部显示眠宝阅读陪伴。", "fields": "article.sections[][]：每项为小标题和正文文本。", "logic": "完整显示所选文章内容；标题和正文按文本转义后渲染。页面不提供诊断、剂量调整或申请提交等操作；不产生患者记录。"}, {"title": "返回与阅读状态", "description": "顶部返回及底部返回文章列表按钮，二级页面隐藏主导航。", "fields": "stack、knowledgeFilter、knowledgeScrollTop。", "logic": "正常从列表进入时返回上一层，保留分类与位置。失效 ID 的返回知识中心按钮直接打开列表。当前不保存已读、阅读时长、收藏或分享记录。"}];
PAGE_MODULES.home = [{"title": "首次登录建档引导", "description": "手机号授权后到达首页，无健康档案时展示带眠宝的建档提示弹窗。", "fields": "onboardingPending、patientArchive；目标 patientArchive。", "logic": "点击建立档案进入两字段表单，稍后再说关闭提示；已有档案不展示。刷新时未处理的提示保留；不影响首页原任务与服务。"}, {"title": "眠宝权益卡", "description": "根据商保状态与今日用药记录展示对应文案；点击文案进入下一步，点击眠宝切换预览状态。", "fields": "当前字段补齐：insuranceStatus、meds[].day、homePreviewState。\n建议申请字段（待确认）：applicationId、applicationStatus、benefitStatus、updatedAt、rejectReason。", "logic": "未领取或审核中进入商保页；已领取未记录打开用药弹窗；已记录进入服药记录。\n\n【A02/D01｜现状】未领取/审核中进入 payment；已领取且今日无记录打开服药弹窗；已记录进入 med。点击眠宝可覆盖展示状态，不改变申请数据。\n【建议规则（待确认）】申请状态与权益可用状态分别保存；approved 只有经权益接口确认可用后才映射“已领取”。审核拒绝显示拒绝原因及重申入口，不能映射已领取。状态成功刷新后统一重算首页与支付详情。\n【待确认】未申请/审核中/已通过/已拒绝分别对应的首页文案、按钮、跳转；通过后是否需激活；多个申请取哪一份；申请服务、失效规则。临时展示状态不作为真实办理依据，正式版是否保留点击切换需确认。"}, {"title": "首页滚动 Banner", "description": "晨起状态与眠宝权益卡之后展示三张固定推荐卡片，分别进入健康记录、眠宝帮您和知识中心；支持自动轮播、箭头、指示点、横向滑动和暂停。", "fields": "homeBanners[]：title、text、action、target、theme；bannerStates.home：index、paused。", "logic": "页面顺序为顶部问候→晨起状态和眠宝权益卡→Banner→快捷服务→今日任务。轮播每 5 秒循环；离开页面清除计时器，页面隐藏、轮播内有焦点、主动暂停或系统要求减少动态时暂停。仅更新轮播区域，不清空左侧编辑输入。"}, {"title": "快捷服务", "description": "八个入口：语音病历、病程记录、药房地图、线上购药、多元支付、用药记录、不良反应速记和我的专员。", "fields": "voiceCase、journey、pharmacy、shop、payment、medReminder、adverseForm、specialist。", "logic": "语音病历进入 voiceCase 独立二级页；病程记录进入既有 journey 文字/图片/录音流程；其余入口保留原跳转。所有二级页面隐藏五项主导航，并通过顶部返回回到首页。"}, {"title": "语音病历快捷入口", "description": "点击语音病历进入独立二级页面，由眠宝引导讲述时间、症状和次数。", "fields": "route=voiceCase；historyRoute=voiceCaseHistory；state.voiceCases[]。", "logic": "本次按用户确认仅实现 Demo 展示。点击或长按底部按钮展示固定示例整理效果；不调用麦克风、语音转写或真实大模型。该二级页不展示首页功能栏。"}, {"title": "病程记录快捷入口", "description": "首页点病程记录后直接打开带眠宝的记录表单，可填写文字、上传图片、录制和回放语音。", "fields": "路由 journey；内嵌入口 entry=recordJourney。与眠宝帮您共用 IndexedDB mianbao-integrated-care-records-v1 的 records/media。", "logic": "文字≤2000 字；单条≤4 张图片、单张≤10 MB；单段录音≤2 分钟。文字、图片或语音至少一项；提交前停止录音并等待附件保存。保存到既有病历夹，同一来源可从眠宝帮您回看，不建立独立记录副本。"}, {"title": "今日用药与眠宝引导弹窗", "description": "点击今日用药或首页权益卡的记录按钮，居中弹出眠宝 GIF 引导；确认已按医嘱服药后保存，已记录时显示完成状态与查看入口。", "fields": "settings.medTime；meds[]：id、time、day、note；动效 assets/mianbao-med-guide.gif。", "logic": "点击任务不再直接跳详情；确认后保存当前时间与日期并关闭弹窗，同日该弹窗只保存一次，刷新任务及首页权益文案。已记录点击查看进入服药详情；开启减少动态时以静态眠宝替代 GIF。"}, {"title": "小憩引导弹窗与首页倒计时", "description": "点击日常小憩时钟居中弹出与今日用药同样的眠宝 GIF 卡片，填写时长并添加，随后关闭弹窗并在首页显示倒计时。进行中再次点击可暂停、继续或结束并记录。", "fields": "napSession：id、day、startedAt、totalSeconds、remainingSeconds、endsAt、status(running/paused/finished)；时长 1—120 整数分钟；naps[]：id、day、time、minutes；动效 assets/mianbao-nap-guide.gif。", "logic": "添加时建立计时会话，不计入已完成次数。倒计时每秒按 endsAt 和当前时间计算，不改写整页或左侧编辑内容；切换页面继续，刷新恢复。暂停保存剩余秒数，继续重建 endsAt。到时自动保存一条小憩记录，id 去重，归属开始日期；提前结束至少计时 1 秒才保存，分钟向上取整。保存失败保留会话可重试，不显示虚假完成；取消本次小憩不新增记录；未接入关闭页面后的通知。"}, {"title": "状态打卡", "description": "四档状态选择：精神饱满/有些疲惫/需要小睡/状态不佳；\n选择后下方对应文案变更；", "fields": "moods[本地日期]：四档状态之一。\n建议正式字段（待确认）：userId、recordDate、moodCode、createdAt、updatedAt；recordDate 按选定业务时区生成。", "logic": "同日只能提交一次；已记录时禁用四个选项。\n\n【B02/B03｜现状】四档仅更新“今天的感受”文字；权益主文案由支付和服药记录决定。当前同日一次，不可修改。\n【建议规则（待确认）】晨起记录按 userId + recordDate 唯一；误选通过“修改当日状态”覆盖原记录而非新增，保留修改时间；未选择时显示引导，已选择时显示选中项。跨日重新计算日期及可选状态。\n【待确认】是否开放修改；四档对应反馈文案与形象配置；晨起反馈与权益信息的排列关系；日期统一北京时间还是用户时区。未确认前不把晨起状态当作疾病判断。"}];

