PAGE_MODULES.login = [{"title": "眠宝形象与立即登录", "description": "登录页显示眠宝形象、立即登录按钮及两项协议查看链接。", "fields": "route=login；state.authStatus；loginSession.phoneAuthorized。", "logic": "点击立即登录直接打开手机号授权样式弹窗，不再依次打开用户协议/隐私政策确认弹窗。二级登录页隐藏主导航。"}, {"title": "用户协议与隐私政策查看", "description": "用户主动点击链接才显示对应说明，点击我知道了关闭。", "fields": "sheet=loginTerms/loginPrivacy；文案由协议类型区分。", "logic": "仅供查看，不要求同意并继续，不写入新的协议确认时间；不作为登录的前置拦截。已有协议记录保留，不自动伪造确认。正式协议正文及正式授权规则待接入。"}, {"title": "手机号授权与登录结果", "description": "展示微信默认手机号授权样式；拒绝或允许由用户操作。", "fields": "sheet=wechatPhone；authStatus=active；loginSession：phoneAuthorized、authorizedAt；onboardingPending。", "logic": "拒绝保留登录页；允许后写入登录状态并到达首页。仅允许在登录页且当前授权弹窗打开时确认；保存失败恢复原状态。无档案仍保留首次建档引导，有档案不重复提示。当前为授权样式 Demo，不接真实微信服务。"}];
