PAGE_MODULES.journey = [{"title": "眠宝引导与记录入口", "description": "顶部返回、查看记录入口，眠宝提示上传就诊与处方材料。", "fields": "route=journey；route.caseId；historyRoute=journeyHistory。", "logic": "替换首页原内嵌文字/图片/语音表单。新页主要为图片材料与信息提取；眠宝帮您中的既有文字/语音病历夹保留。本页不再内嵌 iframe，不显示主导航。"}, {"title": "上传与拍照", "description": "上传支持多选；拍照使用设备的图片拍摄入口。图片可放大预览或移除。", "fields": "documentUi.images[]：id、name、source(upload/camera)、dataUrl；documentUpload.multiple；documentCamera.capture=environment。", "logic": "最多 4 张，单张≤10 MB；支持 JPEG/PNG/WebP。拍照是否打开摄像头由浏览器/设备决定，桌面可回退文件选择。检查格式、数量、大小并解码后，最长边压缩到1280px、JPEG质量0.78。批量处理失败保留原图片，不部分追加；离页后未完成处理不再写入当前草稿。"}, {"title": "提取流程与状态", "description": "选图后点击提取，显示整理中状态，随后展示就诊和用药两组信息。", "fields": "documentUi.phase=empty/uploading/ready/extracting/result；job、timer、extractedAt；extractionSource=demo。", "logic": "本次用户确认仅做 Demo 提取效果，约1.2秒后显示固定示例，不进行真实 OCR 或模型调用，不把任意上传图片当作已识别事实。提取示例标签保留；处理中禁用上传/移除/提取等重复操作。增删图片后原结果失效，需要重新提取；离页取消待完成任务。"}, {"title": "就诊信息与用药信息核对", "description": "就诊日期、医院、科室、就诊原因、就诊记录；药品名称、处方用药信息、用药时间、其他备注。", "fields": "fields：visitDate(YYYY-MM-DD)、hospital、department、chiefComplaint、visitSummary、drugNames、dosageText、medicationPeriod、notes。", "logic": "用户可修改或清空字段；长文本≤1000字，单行≤100字。填写日期时校验有效且不晚于北京时间当天；至少保留一项就诊/用药信息。示例不提供诊断结论或处方建议，不自动写入用药任务和猝倒统计。"}, {"title": "保存与重新上传", "description": "确认保存保留图片和字段；成功后禁用保存。重新上传开始新的草稿。", "fields": "state.documentCases[]：id、createdAt、updatedAt、extractedAt、extractionSource、fields、images；存储键 mianbao-prototype-v1；documentUi.recordId、saved。", "logic": "首次保存新增，回看记录修改后按同一 ID 更新并保留 createdAt；重复保存不新增。保存失败恢复原数组并保留草稿可重试。重新上传不删除旧记录；新草稿离开页面不保留。记录与主应用一起清理，未接云端或账号服务。"}];
PAGE_MODULES.journeyHistory = [{"title": "记录列表与空状态", "description": "卡片显示首张材料缩略图、医院/药品名称、就诊日期、材料数和更新时间。", "fields": "state.documentCases[]：id、images、fields、updatedAt。", "logic": "按更新时间倒序，只显示成功保存的记录；无记录提示上传并核对保存，不显示未保存草稿。"}, {"title": "回看与更新", "description": "点击记录带 caseId 进入材料与字段详情。", "fields": "route.caseId；documentUi.recordId、saved。", "logic": "读取同一数组，不重新计算已保存字段或再次提取。原状态为已保存，修改后开放保存并更新同一 ID。顶部返回回到原列表；二级页不显示主导航。"}];
PAGE_MODULES.voiceCaseHistory = [{"title": "历史列表与空状态", "description": "顶部返回；无记录时显示眠宝空状态，不展示新增语音病历按钮。", "fields": "state.voiceCases[]；route=voiceCaseHistory。", "logic": "仅显示已成功保存的数据，未保存草稿不计入列表。新建从首页语音病历入口进入，历史列表不提供新建按钮。"}, {"title": "记录列表与排序", "description": "卡片展示发作日期、提取症状、次数原话及保存时间。", "fields": "id、time.convertedDate、symptoms.extracted、count.originalDescription、createdAt。", "logic": "按 createdAt 倒序展示；记录发生日期与保存时间分别展示，不相互覆盖。列表与“我的记录”中语音病历条数读取同一数组。"}, {"title": "病历详情回看", "description": "点击卡片回到语音病历页，显示已保存完整内容。", "fields": "route.caseId；voiceCases[].id；savedId。", "logic": "按 ID 读取，保留当时原话与日期换算结果；保存按钮禁用以防重复。可按住再记录生成新的病历，不覆盖原记录。本期无编辑、单条删除或自动写入猝倒趋势。"}];
PAGE_MODULES.records = [{"title": "记录分类", "description": "病程记录、语音病历、服药、猝倒、睡眠和 ESS 六类入口。", "fields": "documentCases、voiceCases、meds、events、sleep、ess 的数组长度及对应路由。", "logic": "数量按数组长度实时计算。\n\n【C10｜现状】仅五类，不含小憩、照片/SRSS、游戏、预约与晨起状态。\n【建议规则（待确认）】用一份类别配置供“我的记录/全部记录”；展示每类有效记录全量条数，不含草稿/失败；测评按记录统一列表，明确有分数与无分数照片是否计数。\n【待确认】本期类别清单；未纳入类型是否有其他全量入口；重复来源与任务计数不能混用。"}, {"title": "分类跳转", "description": "点击分类进入对应记录列表。", "fields": "目标页面。\n建议 target、filters、pageCursor、returnTarget；所有私有数据绑定 userId。", "logic": "病程记录进入 journeyHistory；语音病历进入 voiceCaseHistory；其他分类保留对应列表。不提供不良反应速记入口；条数只统计成功保存的数据。"}];
PAGE_MODULES.ai = [{"title": "眠宝欢迎与咨询", "description": "显示小绵羊欢迎、热门问题和自由咨询；支持本地关键词匹配、多意图合并与超范围回复。", "fields": "服务独立状态 mianbao-integrated-service-v1；sessions[]、messages[]。", "logic": "欢迎区仅展示眠宝形象与介绍，点击问问眠宝进入咨询；不展示或写入每日状态记录。会话超过 3 天未互动新建，历史保留近 12 个月；AI 为本地规则匹配，医学与政策内容待正式审核。该模块数据不改写首页、专病管理、权益中心与我的现有记录。"}, {"title": "创新支付、入组与援助申请", "description": "展示入组、福利订单和直付/后报销进度；在会话中逐步完善资料、上传材料、核对提交，支持暂停、恢复、重新填写及驳回补件。", "fields": "enrollment、type、code、patient、orders[]、aidDrafts 与会话 careFlows；材料图片本地保存。", "logic": "保留源模块的状态字典与订单过滤：20 区分药房审核阶段、21 过滤；后报销需处方与发票，直付含用药数量。申请提交为本地流程，未接保险/审核/理赔接口；不改变首页患者福利的状态。"}, {"title": "病历夹与用药记录", "description": "聊天中记录病程文字、录制语音、上传图片；支持时间线、类型筛选、音频回放、图片放大和用药记录。", "fields": "IndexedDB mianbao-integrated-care-records-v1 的 records、media；记录时间、文字、媒体、药品、用药状态、备注。", "logic": "语音为录音与回放，不含语音转文字；每段最长 2 分钟，图片每条最多 4 张，单文件最多 10 MB，图片压缩后保存。记录时间不能在未来，保存前需停止录音；用药状态含已服用/漏服/暂停，新增记录不提供医学建议。"}, {"title": "健康科普", "description": "先在聊天中展示三篇推荐文章；查看更多展开六篇文章及分类，支持全文阅读、收起与展开。", "fields": "源模块 articles[]、articleFilter、articleId 与消息 kind=articles/appPanel。", "logic": "所有文章操作保持在眠宝会话内；内容为记录与资料整理说明，正式医学内容和发布审核接口待接入。"}, {"title": "客服与我的服务", "description": "真人客服入口；头像展开患者资料、历史会话和福利关爱记录。", "fields": "patient、sessions[]、orders[]；历史会话分页；申请人姓名打码。reports[] 仅保留旧数据兼容，不新增事件记录。", "logic": "移除疑似不良事件记录入口、确认表单及保存流程；用药相关咨询仍可回答一般说明并引导联系医生/药师，不生成事件报告。旧记录保留，不因功能移除而擦除数据。"}, {"title": "会话快捷操作与状态设置", "description": "发起会话后，输入区上方展示可横向滑动的创新支付、记录病程、用药记录、真人客服；状态按钮保留源模块场景切换和数据重置。", "fields": "activeSession、view、conversationActions；入组/支付/订单状态控件。", "logic": "首屏与空会话不显示快捷按钮；状态设置只更新本服务模块。清空聊天保留说明、病历、用药与订单；重置仅清理本服务模块数据。宿主左侧说明及右侧修改意见沿用原保存机制。"}];
PAGE_MODULES.payment = [{"title": "权益状态", "description": "展示未领取、审核中或已领取，并可切换本地状态。", "fields": "insuranceStatus：unclaimed / reviewing / claimed。\n建议申请状态 applicationStatus，与 benefitStatus 分开；applicationId、userId、serviceType、updatedAt、rejectReason、version。", "logic": "状态切换后首页权益文案同步重算；不能作为真实资格结论。\n\n【A02/D01｜现状】本地三态由按钮切换，尚无拒绝和真实审核。\n【建议规则（待确认）】未申请→提交成功→审核中→服务端通过或拒绝；拒绝可查看原因，满足条件重申创建新申请且保留历史。审核中只允许已确认操作；通过不直接等于已领取，需要权益接口确认可用。查询失败保留上次状态并标过期/重试，不归零。\n【待确认】资格、补件/撤回/重申/到期、激活领取、各态按钮和首页映射、多个申请选取。仅说明建议，不把本地切换作为正式审核操作。"}, {"title": "预计流程", "description": "展示资格、保单处方核验和支付渠道三个步骤。", "fields": "正式资格与渠道字段待接入。\n建议申请材料字段由业务配置：eligibility、requiredDocuments、consentVersion、clientRequestId；结果含申请编号和提交时间。", "logic": "当前不向保险机构提交申请。\n\n【D01/E02｜建议规则（待确认）】先资格/材料校验并确认授权，再提交；提交中禁用；失败保留材料允许重试；同幂等键只生成一单；成功显示申请编号与进度入口。通过后展示真实领取/渠道操作，失败与拒绝区分。\n【待确认】本期仅查看还是可办理、正式字段/合作方/审核时效/材料保存、渠道失效、重复申请、与福利共享或独立。\n\n【E02/E03｜通用建议（待确认）】存在保存/删除/查询时，加载、成功、失败和空数据分别显示；失败保留输入或原数据，不伪造完成。重复请求使用记录级标识去重；未保存离开提示；新增/修改/删除成功刷新依赖统计。只读页面无额外数据写入。\n【E06｜说明版本】“现状”描述当前界面；“建议规则（待确认）”是开发方案供业务确认；“待实现”只指说明中的新模块。旧页面通用规则与本模块建议冲突时先确认再实现，不能视为中间页面已经变更。\n【已确认｜二级导航】本页面隐藏底部五项一级导航栏，内容区占用释放的底部空间；使用顶部返回按钮回到来源页。仅首页、健康档案、眠宝帮您、知识中心、我的显示底部导航。"}];
PAGE_MODULES.rights = [{"title": "知识中心导航与眠宝引导", "description": "页面标题及底部导航显示知识中心，顶部以医生形象眠宝引导阅读。", "fields": "导航 label=知识中心；route=rights（保留原路由键）；首页 homeBanners[2].target=rights。", "logic": "权益中心页面整体替换为知识中心，不展示创新支付状态卡、保障服务卡或 Banner。首页患者福利及眠宝帮您中已有申请功能保留；标题更名不改变支付数据。"}, {"title": "文章分类筛选", "description": "显示全部、就医准备、日常记录、用药记录、援助服务分类，可横向滚动。", "fields": "knowledgeCategories 由文章分类去重；knowledgeFilter；knowledgeArticles[].category。", "logic": "默认全部，点击分类只更新筛选按钮和文章列表，不重绘整页或清空左侧编辑内容；分类及列表位置在当前会话保留，刷新回到全部。"}, {"title": "患教文章列表", "description": "显示文章分类、预计阅读时长、标题和摘要，点击整张文章卡片阅读。", "fields": "knowledgeArticles[]：id、category、title、summary、read、icon、theme、sections[][]；当前 6 篇本地文章。", "logic": "按配置顺序展示，分类过滤与篇数使用同一结果；无匹配时显示空列表提示。正文复用既有眠宝模块中的记录与资料整理内容，暂不接文章管理后台。"}, {"title": "详情跳转与回到列表", "description": "点击文章以唯一 ID 进入文章详情，返回列表可继续浏览。", "fields": "route=articleDetail；route.articleId；knowledgeScrollTop。", "logic": "进入详情前保存列表滚动位置；返回读取同一目录并恢复当前分类和位置，不创建新会话或患者记录。详情为二级页，隐藏首页功能栏。"}];
