PAGE_MODULES.journey = [{"title": "统一入口与页面结构", "description": "仅保留首页病程记录入口。顶部返回/查看记录，中间独立滚动，底部固定语音按钮和保存按钮。", "fields": "route=journey；route.caseId；journeyHistory；journeyUi.key/record/dirty；app--journey-record。", "logic": "原语音病历入口移除；原 voiceCase/voiceCaseHistory 跳转兼容映射到新模块及列表。二级页隐藏主导航。一次经历一条记录，图片和语音可互相补充；不同经历保存后点再记一条。"}, {"title": "图片选择、拍照与原图预览", "description": "从相册选择支持多选；拍照使用设备图片拍摄入口；上传后自动整理，原图可放大或移除。", "fields": "record.images[]：id、name、source(upload/camera)、dataUrl；journeyUpload.multiple；journeyCamera.capture=environment。", "logic": "最多4张、单张≤10MB，支持JPEG/PNG/WebP。数量/格式/大小校验后解码，最长边1280px，JPEG质量0.78；保存压缩图片。取消选择不改记录，批次处理失败不部分追加。设备决定摄像头或文件选择行为。移除图片保留已填写信息并提示核对；无任何来源时不能保存。"}, {"title": "图片信息提取与结果合并", "description": "上传成功后显示 loading 弹窗，回显原始图片、三类关键信息和就诊/用药补充信息。", "fields": "journeyUi.phase=uploading/extracting/idle；record.facts、visitInfo、extractedAt；journeyProvider().extract({kind,image/text,images,referenceAt,signal})。", "logic": "本次继续采用用户已确认的 Demo：没有真实OCR或大模型调用。固定示例不视为上传材料的真实识别结果，页面保留提取示例标记。图片补全尚空的核心字段，并提供就诊用药字段；不覆盖用户手动修改的字段。原图不因模型失败而删除。"}, {"title": "长按语音与微信样式弹窗", "description": "按住显示麦克风、波形和时长；上滑进入取消状态，松开取消或结束。", "fields": "phase=recording；holdStart、holdY、cancelVoice、holdTimer；voiceReferenceAt、voiceDuration；上滑阈值70px。", "logic": "按住至少500ms，太短提示重新按住；最长60秒自动结束。上滑70px以上松手取消，移回可继续；指针取消、失去捕获、Escape、窗口失焦或切到后台均取消，保留已有内容。触屏阻止滚动与系统长按菜单；支持空格/回车长按及辅助技术激活。Demo展示录音交互和固定转写，不采集真实麦克风或音频。"}, {"title": "语音转文字与模型等待弹窗", "description": "松开后先显示转换文字，再显示整理信息的 loading 弹窗；可取消等待。", "fields": "phase=transcribing/extracting；controller、job、retryKind、retryReanalyse；服务接口 transcribe/extract；超时20秒。", "logic": "两段异步任务均等待完成后才回显；取消或离页后晚到结果不能覆盖当前页。超时或失败关闭弹窗，保留已有图片、已完成转写文字和旧字段，提供重新整理或手动填写。转写本身未完成时需要重新记录或重试；正式版需接录音/ASR并保留音频，当前Demo没有实际音频文件。"}, {"title": "原始描述、核心字段与标红回显", "description": "展示可修正的语音识别原文，以及时间、症状、次数的原文和提取值；整理描述随字段编辑同步更新。", "fields": "originalTranscript：首次识别原文保留；originalText：可修正文本≤2000字；voiceSegments[]：id、text、referenceAt、durationMs；facts：timeOriginal、date(YYYY-MM-DD)、period、symptomsOriginal、symptoms、countOriginal、count。", "logic": "所有提取字段可编辑。三类有效信息在整理描述中标红，缺失标待补充/未提及；未提及次数不填0。次数保留约三次/2—3次等不确定描述，不强制精确整数。相对日期以首次语音的北京时间 referenceAt 为锚点，历史回看不按今天重算；不明确日期可留空，填写时校验有效且不晚于当天。修正原文后可重新整理，明确手动改过的字段优先保留。"}, {"title": "图片与语音互补及就诊用药信息", "description": "同一记录可同时包含图片和语音。就诊/用药补充字段折叠展示，也可全部编辑。", "fields": "visitInfo：hospital、department、chiefComplaint、visitSummary、drugNames、dosageText、medicationPeriod、notes；journeyUi.edited；record.userEditedFields。", "logic": "图片补充就诊和用药材料；语音优先更新未手动修改的核心字段。新增语音追加到识别原文，不删除原图片或已有描述；各段原文与时点分别保留。医院/科室/药品及备注可核对修改。不同日期或来源冲突由患者核对，不自动判定诊断、用药建议或病情严重程度。"}, {"title": "草稿、保存与历史兼容", "description": "未完成内容保存为草稿，返回/刷新可恢复；确认保存后禁用重复保存，可再次新建。旧图片与语音记录统一可见。", "fields": "state.journeyRecords[]；state.journeyDrafts 按new/recordId保存草稿；兼容 journeyDraft；record：id、createdAt、updatedAt、referenceAt、timeZone、images、originalText、originalTranscript、voiceSegments、facts、visitInfo、extractedAt、extractionSource、optimizedText、userEditedFields、legacy。", "logic": "草稿输入300ms防抖保存，离页及时保存；草稿不计入历史数量。保存失败恢复原数组并保留修改，可重试；草稿保存失败离页提示真实丢失风险。首次保存新增，之后按同一ID更新，保留创建时间。旧voiceCases/documentCases通过voice:/image:前缀兼容映射；更新写新数组并按ID去重，旧数据不删除。记录与草稿共用主应用存储，注销/清除主存储同时清理。不自动写入猝倒趋势或今日用药任务。"}];
PAGE_MODULES.journeyHistory = [{"title": "统一列表与分类筛选", "description": "按更新时间倒序展示，标记图片、语音或图片+语音，并显示日期、症状与次数。", "fields": "allJourneyRecords()；journeyHistoryFilter=全部/图片/语音；id、updatedAt/createdAt、images、originalText、facts。", "logic": "全部按稳定ID去重；混合记录在图片和语音分类中均显示，但总条数只计一次。没有次数显示未提及，不将其视为0次。列表只显示已成功保存记录，不计草稿。不展示新增语音病历按钮。"}, {"title": "旧记录兼容与编辑回看", "description": "旧语音和图片记录仍可打开；修改后保存到同一条记录。", "fields": "legacy.kind/id；voice:旧ID、image:旧ID；route.caseId；journeyDrafts[recordId]。", "logic": "只读映射旧数组，不破坏原始历史；覆盖修改以相同稳定ID写新数组，合并读取时新值优先，避免双份显示。回看不重新调用提取，不重算相对日期；未保存编辑可从草稿恢复。顶端返回回到来源页面。"}];
PAGE_MODULES.home = [{"title": "首次登录建档引导", "description": "手机号授权后到达首页，无健康档案时展示带眠宝的建档提示弹窗。", "fields": "onboardingPending、patientArchive；目标 patientArchive。", "logic": "点击建立档案进入两字段表单，稍后再说关闭提示；已有档案不展示。刷新时未处理的提示保留；不影响首页原任务与服务。"}, {"title": "眠宝权益卡", "description": "根据商保状态与今日用药记录展示对应文案；点击文案进入下一步，点击眠宝切换预览状态。", "fields": "当前字段补齐：insuranceStatus、meds[].day、homePreviewState。\n建议申请字段（待确认）：applicationId、applicationStatus、benefitStatus、updatedAt、rejectReason。", "logic": "未领取或审核中进入商保页；已领取未记录打开用药弹窗；已记录进入服药记录。\n\n【A02/D01｜现状】未领取/审核中进入 payment；已领取且今日无记录打开服药弹窗；已记录进入 med。点击眠宝可覆盖展示状态，不改变申请数据。\n【建议规则（待确认）】申请状态与权益可用状态分别保存；approved 只有经权益接口确认可用后才映射“已领取”。审核拒绝显示拒绝原因及重申入口，不能映射已领取。状态成功刷新后统一重算首页与支付详情。\n【待确认】未申请/审核中/已通过/已拒绝分别对应的首页文案、按钮、跳转；通过后是否需激活；多个申请取哪一份；申请服务、失效规则。临时展示状态不作为真实办理依据，正式版是否保留点击切换需确认。"}, {"title": "首页滚动 Banner", "description": "晨起状态与眠宝权益卡之后展示三张固定推荐卡片，分别进入健康记录、眠宝帮您和知识中心；支持自动轮播、箭头、指示点、横向滑动和暂停。", "fields": "homeBanners[]：title、text、action、target、theme；bannerStates.home：index、paused。", "logic": "页面顺序为顶部问候→晨起状态和眠宝权益卡→Banner→快捷服务→今日任务。轮播每 5 秒循环；离开页面清除计时器，页面隐藏、轮播内有焦点、主动暂停或系统要求减少动态时暂停。仅更新轮播区域，不清空左侧编辑输入。"}, {"title": "快捷服务", "description": "六个入口：病程记录、药房地图、线上购药、患者福利、用药记录和我的专员。", "fields": "journey、pharmacy、shop、payment、medReminder、specialist。", "logic": "语音病历与病程记录合并，仅保留一个病程记录入口；该页支持图片、拍照和长按语音。其余入口保留原逻辑。"}, {"title": "病程记录快捷入口", "description": "进入统一病程记录页面，通过图片或语音记录时间、症状、次数，并可编辑保存。", "fields": "journey/journeyHistory；journeyRecords[]、journeyDrafts；旧 voiceCases/documentCases 兼容读取。", "logic": "未完成记录可恢复草稿；旧图片与语音记录保留在统一历史。当前提取为Demo效果，保存后不自动生成猝倒事件或服药任务。"}, {"title": "今日用药与眠宝引导弹窗", "description": "点击今日用药或首页权益卡的记录按钮，居中弹出眠宝 GIF 引导；确认已按医嘱服药后保存，已记录时显示完成状态与查看入口。", "fields": "settings.medTime；meds[]：id、time、day、note；动效 assets/mianbao-med-guide.gif。", "logic": "点击任务不再直接跳详情；确认后保存当前时间与日期并关闭弹窗，同日该弹窗只保存一次，刷新任务及首页权益文案。已记录点击查看进入服药详情；开启减少动态时以静态眠宝替代 GIF。"}, {"title": "小憩引导弹窗与首页倒计时", "description": "点击日常小憩时钟居中弹出与今日用药同样的眠宝 GIF 卡片，填写时长并添加，随后关闭弹窗并在首页显示倒计时。进行中再次点击可暂停、继续或结束并记录。", "fields": "napSession：id、day、startedAt、totalSeconds、remainingSeconds、endsAt、status(running/paused/finished)；时长 1—120 整数分钟；naps[]：id、day、time、minutes；动效 assets/mianbao-nap-guide.gif。", "logic": "添加时建立计时会话，不计入已完成次数。倒计时每秒按 endsAt 和当前时间计算，不改写整页或左侧编辑内容；切换页面继续，刷新恢复。暂停保存剩余秒数，继续重建 endsAt。到时自动保存一条小憩记录，id 去重，归属开始日期；提前结束至少计时 1 秒才保存，分钟向上取整。保存失败保留会话可重试，不显示虚假完成；取消本次小憩不新增记录；未接入关闭页面后的通知。"}, {"title": "状态打卡", "description": "四档状态选择：精神饱满/有些疲惫/需要小睡/状态不佳；\n选择后下方对应文案变更；", "fields": "moods[本地日期]：四档状态之一。\n建议正式字段（待确认）：userId、recordDate、moodCode、createdAt、updatedAt；recordDate 按选定业务时区生成。", "logic": "同日只能提交一次；已记录时禁用四个选项。\n\n【B02/B03｜现状】四档仅更新“今天的感受”文字；权益主文案由支付和服药记录决定。当前同日一次，不可修改。\n【建议规则（待确认）】晨起记录按 userId + recordDate 唯一；误选通过“修改当日状态”覆盖原记录而非新增，保留修改时间；未选择时显示引导，已选择时显示选中项。跨日重新计算日期及可选状态。\n【待确认】是否开放修改；四档对应反馈文案与形象配置；晨起反馈与权益信息的排列关系；日期统一北京时间还是用户时区。未确认前不把晨起状态当作疾病判断。"}];
