PAGE_MODULES.home = [{"title": "首次登录建档引导", "description": "手机号授权后到达首页，无健康档案时展示带眠宝的建档提示弹窗；不显示右上角关闭按钮。", "fields": "onboardingPending、patientArchive；目标 patientArchive。", "logic": "点击建立档案进入两字段表单；点击稍后再说或遮罩关闭提示，已有档案不展示。刷新时未处理的提示保留；不影响首页原任务与服务。"}, {"title": "眠宝权益卡", "description": "根据商保状态与今日用药记录展示对应文案；点击文案进入下一步，点击眠宝切换预览状态。", "fields": "当前字段补齐：insuranceStatus、meds[].day、homePreviewState。\n建议申请字段（待确认）：applicationId、applicationStatus、benefitStatus、updatedAt、rejectReason。", "logic": "未领取或审核中进入商保页；已领取未记录打开用药弹窗；已记录进入服药记录。\n\n【A02/D01｜现状】未领取/审核中进入 payment；已领取且今日无记录打开服药弹窗；已记录进入 med。点击眠宝可覆盖展示状态，不改变申请数据。\n【建议规则（待确认）】申请状态与权益可用状态分别保存；approved 只有经权益接口确认可用后才映射“已领取”。审核拒绝显示拒绝原因及重申入口，不能映射已领取。状态成功刷新后统一重算首页与支付详情。\n【待确认】未申请/审核中/已通过/已拒绝分别对应的首页文案、按钮、跳转；通过后是否需激活；多个申请取哪一份；申请服务、失效规则。临时展示状态不作为真实办理依据，正式版是否保留点击切换需确认。"}, {"title": "首页滚动 Banner", "description": "晨起状态与眠宝权益卡之后展示三张固定推荐卡片，分别进入健康记录、眠宝帮您和知识中心；支持自动轮播、箭头、指示点、横向滑动；不显示暂停按钮。", "fields": "homeBanners[]：title、text、action、target、theme；bannerStates.home：index。", "logic": "页面顺序为顶部问候→晨起状态和眠宝权益卡→Banner→NT1专区→今日任务。轮播每 5 秒循环；离开页面清除计时器，页面隐藏、轮播内有焦点或系统要求减少动态时暂停。仅更新轮播区域，不清空左侧编辑输入。"}, {"title": "NT1专区", "description": "区域标题为NT1专区。六个入口：病程记录、药房地图、线上购药、患者福利、用药记录和我的专员。", "fields": "journey、pharmacy、shop、payment、medReminder、specialist。", "logic": "语音病历与病程记录合并，仅保留一个病程记录入口；该页支持图片、拍照和长按语音。其余入口保留原逻辑。"}, {"title": "病程记录快捷入口", "description": "进入统一病程记录页面，通过图片或语音记录时间、症状、次数，并可编辑保存。", "fields": "journey/journeyHistory；journeyRecords[]、journeyDrafts；旧 voiceCases/documentCases 兼容读取。", "logic": "未完成记录可恢复草稿；旧图片与语音记录保留在统一历史。当前提取为Demo效果，保存后不自动生成猝倒事件或服药任务。"}, {"title": "今日用药与眠宝引导弹窗", "description": "点击今日用药或首页权益卡的记录按钮，居中弹出眠宝 GIF 引导；确认已按医嘱服药后保存，已记录时显示完成状态与查看入口。", "fields": "settings.medTime；meds[]：id、time、day、note；动效 assets/mianbao-med-guide.gif。", "logic": "点击任务不再直接跳详情；确认后保存当前时间与日期并关闭弹窗，同日该弹窗只保存一次，刷新任务及首页权益文案。已记录点击查看进入服药详情；开启减少动态时以静态眠宝替代 GIF。"}, {"title": "小憩引导弹窗与首页倒计时", "description": "点击日常小憩时钟居中弹出与今日用药同样的眠宝 GIF 卡片，填写时长并添加，随后关闭弹窗并在首页显示倒计时。进行中再次点击可暂停、继续或结束并记录。", "fields": "napSession：id、day、startedAt、totalSeconds、remainingSeconds、endsAt、status(running/paused/finished)；时长 1—120 整数分钟；naps[]：id、day、time、minutes；动效 assets/mianbao-nap-guide.gif。", "logic": "添加时建立计时会话，不计入已完成次数。倒计时每秒按 endsAt 和当前时间计算，不改写整页或左侧编辑内容；切换页面继续，刷新恢复。暂停保存剩余秒数，继续重建 endsAt。到时自动保存一条小憩记录，id 去重，归属开始日期；提前结束至少计时 1 秒才保存，分钟向上取整。保存失败保留会话可重试，不显示虚假完成；取消本次小憩不新增记录；未接入关闭页面后的通知。"}, {"title": "状态打卡", "description": "四档状态选择：精神饱满/有些疲惫/需要小睡/状态不佳；\n选择后下方对应文案变更；", "fields": "moods[本地日期]：四档状态之一。\n建议正式字段（待确认）：userId、recordDate、moodCode、createdAt、updatedAt；recordDate 按选定业务时区生成。", "logic": "同日只能提交一次；已记录时禁用四个选项。\n\n【B02/B03｜现状】四档仅更新“今天的感受”文字；权益主文案由支付和服药记录决定。当前同日一次，不可修改。\n【建议规则（待确认）】晨起记录按 userId + recordDate 唯一；误选通过“修改当日状态”覆盖原记录而非新增，保留修改时间；未选择时显示引导，已选择时显示选中项。跨日重新计算日期及可选状态。\n【待确认】是否开放修改；四档对应反馈文案与形象配置；晨起反馈与权益信息的排列关系；日期统一北京时间还是用户时区。未确认前不把晨起状态当作疾病判断。"}];
