PAGE_MODULES.home = [{"title": "首次登录建档引导", "description": "手机号授权后到达首页，无健康档案时展示带眠宝的建档提示弹窗；不显示右上角关闭按钮。", "fields": "onboardingPending、patientArchive；目标 patientArchive。", "logic": "点击建立档案进入两字段表单；点击稍后再说或遮罩关闭提示，已有档案不展示。刷新时未处理的提示保留；不影响首页其他服务。"}, {"title": "眠宝权益卡", "description": "根据商保状态与今日用药记录展示眠宝反馈。未领取状态只展示静态提示，不显示查看商保直付按钮；其他状态沿用原有操作。", "fields": "当前字段补齐：insuranceStatus、meds[].day、homePreviewState。\n建议申请字段（待确认）：applicationId、applicationStatus、benefitStatus、updatedAt、rejectReason。", "logic": "homeStatus计算当前展示状态。unclaimed显示“您的用药权益暂未领取”和晨起提示，使用静态容器，不绑定homeCardAction；申请入口仍在NT1专区的患者福利。reviewing点击查看审核状态进入payment；claimed-unrecorded点击记录今日用药打开眠宝GIF弹窗；claimed-recorded进入服药记录。点击眠宝切换展示态，不改写申请数据。今日任务区域已移除，不再展示任务卡片或首页小憩倒计时。已有用药、小憩数据及进行中的会话不因此删除。\n正式申请状态、权益可用状态和文案映射需业务方确认；本次仅移除未领取状态的直付按钮，不改变其他状态映射。"}, {"title": "首页滚动 Banner", "description": "晨起状态与眠宝权益卡之后展示三张固定推荐卡片，分别进入健康记录、眠宝帮您和知识中心；支持自动轮播、箭头、指示点、横向滑动；不显示暂停按钮。", "fields": "homeBanners[]：title、text、action、target、theme；bannerStates.home：index。", "logic": "页面顺序为顶部问候→晨起状态和眠宝权益卡→Banner→NT1专区。轮播每 5 秒循环；离开页面清除计时器，页面隐藏、轮播内有焦点或系统要求减少动态时暂停。仅更新轮播区域，不清空左侧编辑输入。"}, {"title": "NT1专区", "description": "区域标题为NT1专区。六个入口：病程记录、药房地图、线上购药、患者福利、用药记录和我的专员。患者福利按钮右上方显示申请状态角标，默认未申请。", "fields": "journey、pharmacy、shop、payment、medReminder、specialist。\n角标来自paymentSummary().label；insuranceStatus=unclaimed/reviewing/applied/claimed/rejected。", "logic": "语音病历与病程记录合并，仅保留一个病程记录入口；该页支持图片、拍照和长按语音。其余入口保留原逻辑。\n未申请显示未申请，reviewing显示审核中；applied/claimed/rejected沿用既有三态概览映射为已申请，具体已申请含义仍待业务定义。角标随状态重绘更新，不额外保存状态，不改变按钮目标。"}, {"title": "病程记录快捷入口", "description": "进入病程记录后，先从底部弹窗选择语音或图片方式，再进入对应录入页；草稿和历史按已选方式恢复。", "fields": "journey/journeyHistory；journeyRecords[]、journeyDrafts；旧 voiceCases/documentCases 兼容读取。", "logic": "新建选择语音/图片，取消返回来源；有内容可切换方式补充而不丢资料。未完成记录可恢复草稿；旧图片与语音记录保留在统一历史。当前提取为Demo效果，保存后不自动生成猝倒事件或服药任务。"}, {"title": "状态打卡", "description": "四档状态选择：精神饱满/有些疲惫/需要小睡/状态不佳；\n选择后下方对应文案变更；", "fields": "moods[本地日期]：四档状态之一。\n建议正式字段（待确认）：userId、recordDate、moodCode、createdAt、updatedAt；recordDate 按选定业务时区生成。", "logic": "同日只能提交一次；已记录时禁用四个选项。\n\n【B02/B03｜现状】四档仅更新“今天的感受”文字；权益主文案由支付和服药记录决定。当前同日一次，不可修改。\n【建议规则（待确认）】晨起记录按 userId + recordDate 唯一；误选通过“修改当日状态”覆盖原记录而非新增，保留修改时间；未选择时显示引导，已选择时显示选中项。跨日重新计算日期及可选状态。\n【待确认】是否开放修改；四档对应反馈文案与形象配置；晨起反馈与权益信息的排列关系；日期统一北京时间还是用户时区。未确认前不把晨起状态当作疾病判断。"}];
PAGE_MODULES.special = [{"title": "本月猝倒记录", "description": "仅展示本月已记录猝倒次数、眠宝反馈和快速记录按钮；不再展示今日次数。", "fields": "events[].day、本月与上月事件数。\n建议统计参数：periodStart、periodEnd、comparisonStart、comparisonEnd、count、comparisonCount、hasRecordedData。", "logic": "月度反馈按已记录次数比较；快速记录保存后更新本月次数和受影响的周趋势，不展示今日次数。\n\n【C03｜现状】本月累计条数直接与上个完整月比较；上月 0 条进入无上月记录文案。统计是已记录次数，不是完整发作次数。\n【建议规则（待确认）】默认对比同等经过天数；展示两个区间及记录次数，用“记录增加/减少/持平”文案。无记录标“无已记录数据”，不推断没有事件。补录、编辑、删除后重算对应日/月，并清除临时展示覆盖态。\n【待确认】等长区间或整月比较、2 月与大小月截止处理、是否要明确记录“无事件”、月度提示文案。正式版不以记录减少直接得出病情改善。"}, {"title": "猝倒周期趋势", "description": "按周展示每日猝倒次数，支持前后切周与查看所选周记录。", "fields": "weekOffset、events[].day。\n建议趋势字段：periodStart、periodEnd、dayCounts[]、selectedWeek；条目按 occurredAt 过滤。", "logic": "周一至周日聚合；查看记录从底部弹出所选周列表。\n\n【C04｜现状】周图与底部列表按同一 weekOffset/日期过滤；图表无记录画为 0。\n【建议规则（待确认）】周一至周日，同一周范围同时驱动图表与列表；允许历史周，不允许超过当前周；返回时保留选中周。新增/修改/删除后更新受影响周；无数据显示“该周暂无已记录事件”。\n【待确认】最早查询范围、无记录日是否用空标记、是否加入月份/诱因分析。独立 trend 页的入口和保留范围另行确认。"}, {"title": "测评记录", "description": "显示 ESS 量表和 SRSS 量表名称；下方卡片可左右滑动，支持点击量表名称、箭头或键盘方向键切换。", "fields": "scaleCatalog[]：code、name、canAnswer；activeScale；ess[]；scalePhotos[]；scrollLeft 为卡片视图位置。", "logic": "当前量表清单为 ESS、SRSS。名称高亮与当前卡片同步；第一张禁止向前、最后一张禁止向后，不循环。ESS 支持答题/拍照，SRSS 支持拍照；拍照按钮携带对应 scale，不依赖之前打开过哪张卡。切卡只更新选中视图，不重绘页面，不清空左侧编辑内容。趋势沿用现有本周得分计算；正式量表清单、版本、计分及医学审核仍待接入。"}, {"title": "健康档案导航与页面命名", "description": "底部专病管理改为健康档案；左侧分组同步显示健康档案。", "fields": "Tab label=健康档案；route=special；专区页面标题仍为发作性睡病专区。", "logic": "只修改导航和分组名称，保留原路由、页面功能及记录关联，不重建记录。二级页面不展示主导航。 本页不再展示睡眠辅助工具及其中三个入口；仅移除当前页面入口，不清空原有小憩、挑战或睡眠记录。"}];
PAGE_MODULES.mine = [{"title": "个人形象与账户状态", "description": "顶部显示眠宝形象和当前账户状态。", "fields": "authStatus：active / signed-out / closed。\n正式建议 userId、sessionStatus、patientRole、eligibilityStatus、profileSummary；与浏览器 authStatus 区分。", "logic": "退出返回登录页，注销后保留原注销完成状态与重新进入入口。\n\n【E01｜现状】退出/注销仅控制本地访问，不是真实用户身份认证。\n【建议规则（待确认）】退出清除认证会话，账号健康数据按已确认缓存策略处理；换账号不能读上个账号数据；登录过期先确认登录再恢复来源操作；注销不得通过普通重新进入恢复已删除账号记录。\n【待确认】登录方式、用户/家属范围、资格、跨设备同步、退出缓存、登录恢复。"}, {"title": "我的服务", "description": "我的服务分组仅显示个人资料，使用无副说明的紧凑入口。", "fields": "profile：个人资料路由。", "logic": "点击个人资料进入档案摘要二级页；不显示消息通知或我的记录入口。仅调整入口，不删除已有患者档案、消息或健康记录。通知偏好仍在设置页维护，本次不改变设置功能。"}, {"title": "设置", "description": "设置分组仅包含设置入口，不展示任务提醒设置入口。", "fields": "目标路由 accountSettings；settings.notificationEnabled；authStatus。", "logic": "点击设置进入账户设置二级页，保留通知偏好、用户协议、退出登录和注销账号功能。移除任务提醒设置入口不改写用药时间、小憩时长或现有任务数据。退出与注销沿用现有确认及数据处理流程；正式账号认证与数据留存规则待接口定义。"}];

