PAGE_MODULES.home = [{"title": "首次登录建档引导", "description": "手机号授权后到达首页，无健康档案时展示带眠宝的建档提示弹窗；不显示右上角关闭按钮。", "fields": "onboardingPending、patientArchive；目标 patientArchive。", "logic": "点击建立档案进入两字段表单；点击稍后再说或遮罩关闭提示，已有档案不展示。刷新时未处理的提示保留；不影响首页其他服务。"}, {"title": "眠宝权益卡", "description": "根据商保状态和今日用药记录展示静态眠宝反馈，不展示任何状态操作按钮。", "fields": "当前字段补齐：insuranceStatus、meds[].day、homePreviewState。\n建议申请字段（待确认）：applicationId、applicationStatus、benefitStatus、updatedAt、rejectReason。", "logic": "homeStatus计算未领取、审核中、已领取未记录、已领取已记录四种展示态；反馈区域统一使用div，不绑定点击、跳转或弹窗。未记录文案为“今天的用药还未记录”，不再提示在本卡片操作。点击眠宝仍可切换展示态，不改写申请或用药数据。患者福利、用药记录等功能沿用NT1专区原有入口。\n今日任务区域已移除，不展示任务卡片或首页小憩倒计时；不清空已有业务数据。正式申请状态与权益文案映射仍待业务确认。"}, {"title": "首页滚动 Banner", "description": "晨起状态与眠宝权益卡之后展示三张固定推荐卡片，分别进入健康记录、眠宝帮您和知识中心；支持自动轮播、箭头、指示点、横向滑动；不显示暂停按钮。", "fields": "homeBanners[]：title、text、action、target、theme；bannerStates.home：index。", "logic": "页面顺序为顶部问候→晨起状态和眠宝权益卡→Banner→NT1专区。轮播每 5 秒循环；离开页面清除计时器，页面隐藏、轮播内有焦点或系统要求减少动态时暂停。仅更新轮播区域，不清空左侧编辑输入。"}, {"title": "NT1专区", "description": "区域标题为NT1专区。六个入口：病程记录、药房地图、线上购药、患者福利、用药记录和我的专员。患者福利按钮右上方显示申请状态角标，默认未申请。", "fields": "journey、pharmacy、shop、payment、medReminder、specialist。\n角标来自paymentSummary().label；insuranceStatus=unclaimed/reviewing/applied/claimed/rejected。", "logic": "语音病历与病程记录合并，仅保留一个病程记录入口；该页支持图片、拍照和长按语音。其余入口保留原逻辑。\n未申请显示未申请，reviewing显示审核中；applied/claimed/rejected沿用既有三态概览映射为已申请，具体已申请含义仍待业务定义。角标随状态重绘更新，不额外保存状态，不改变按钮目标。"}, {"title": "病程记录快捷入口", "description": "进入病程记录后，先从底部弹窗选择语音或图片方式，再进入对应录入页；草稿和历史按已选方式恢复。", "fields": "journey/journeyHistory；journeyRecords[]、journeyDrafts；旧 voiceCases/documentCases 兼容读取。", "logic": "新建选择语音/图片，取消返回来源；有内容可切换方式补充而不丢资料。未完成记录可恢复草稿；旧图片与语音记录保留在统一历史。当前提取为Demo效果，保存后不自动生成猝倒事件或服药任务。"}, {"title": "状态打卡", "description": "四档状态选择：精神饱满/有些疲惫/需要小睡/状态不佳；\n选择后下方对应文案变更；", "fields": "moods[本地日期]：四档状态之一。\n建议正式字段（待确认）：userId、recordDate、moodCode、createdAt、updatedAt；recordDate 按选定业务时区生成。", "logic": "同日只能提交一次；已记录时禁用四个选项。\n\n【B02/B03｜现状】四档仅更新“今天的感受”文字；权益主文案由支付和服药记录决定。当前同日一次，不可修改。\n【建议规则（待确认）】晨起记录按 userId + recordDate 唯一；误选通过“修改当日状态”覆盖原记录而非新增，保留修改时间；未选择时显示引导，已选择时显示选中项。跨日重新计算日期及可选状态。\n【待确认】是否开放修改；四档对应反馈文案与形象配置；晨起反馈与权益信息的排列关系；日期统一北京时间还是用户时区。未确认前不把晨起状态当作疾病判断。"}];
PAGE_MODULES.special = [{"title": "本月猝倒记录", "description": "显示本月已记录猝倒次数和眠宝反馈；快速记录按钮在卡片底部独立操作区，不覆盖眠宝形象。", "fields": "events[].day、本月与上月事件数。\n建议统计参数：periodStart、periodEnd、comparisonStart、comparisonEnd、count、comparisonCount、hasRecordedData。", "logic": "底部按钮采用正常布局流，点击仍打开猝倒快速记录弹窗。月度反馈按已记录次数比较；快速记录保存后更新本月次数和受影响的周趋势，不展示今日次数。\n\n【C03｜现状】本月累计条数直接与上个完整月比较；上月 0 条进入无上月记录文案。统计是已记录次数，不是完整发作次数。\n【建议规则（待确认）】默认对比同等经过天数；展示两个区间及记录次数，用“记录增加/减少/持平”文案。无记录标“无已记录数据”，不推断没有事件。补录、编辑、删除后重算对应日/月，并清除临时展示覆盖态。\n【待确认】等长区间或整月比较、2 月与大小月截止处理、是否要明确记录“无事件”、月度提示文案。正式版不以记录减少直接得出病情改善。"}, {"title": "猝倒周期趋势", "description": "按周展示每日猝倒次数，支持前后切周与查看所选周记录。", "fields": "weekOffset、events[].day。\n建议趋势字段：periodStart、periodEnd、dayCounts[]、selectedWeek；条目按 occurredAt 过滤。", "logic": "周一至周日聚合；查看记录从底部弹出所选周列表。\n\n【C04｜现状】周图与底部列表按同一 weekOffset/日期过滤；图表无记录画为 0。\n【建议规则（待确认）】周一至周日，同一周范围同时驱动图表与列表；允许历史周，不允许超过当前周；返回时保留选中周。新增/修改/删除后更新受影响周；无数据显示“该周暂无已记录事件”。\n【待确认】最早查询范围、无记录日是否用空标记、是否加入月份/诱因分析。独立 trend 页的入口和保留范围另行确认。"}, {"title": "测评记录", "description": "显示ESS/SRSS量表名称和得分趋势，支持名称、箭头、滑动和键盘切换；移除本周分数及测评与拍照记录说明小字。", "fields": "scaleCatalog[]：code、name、canAnswer；activeScale；ess[]、scalePhotos[]：id、scale、score、day、time；recentScaleRecords(name)返回最近最多7条有效得分记录。", "logic": "ESS汇总答题和ESS照片得分，SRSS只读取SRSS照片得分；空/缺失/无效或负数得分、无有效日期的记录不入图，0分保留。优先按time/createdAt排序，无有效时间时使用day零点，同时间保留来源顺序；取最近7条后由早到晚展示。横坐标按每条记录day显示MM/DD，同日多条分别保留，不合并、不补齐无记录日期；少于7条展示实际数量，无有效得分显示空态。原始时间和年份保留，图表可访问说明包含完整日期及得分。\n保留ESS答题/拍照和SRSS拍照入口，照片归属由按钮携带scale决定。新增得分保存后重算对应量表趋势，不修改原记录。切卡同步名称、高亮和箭头边界；首尾不循环，不重绘整页或清空左侧编辑。猝倒周期趋势仍按自然周展示，与量表记录趋势分开计算。正式量表清单、计分、图片识别及医学审核仍待接入。"}, {"title": "健康档案导航与页面命名", "description": "底部专病管理改为健康档案；左侧分组同步显示健康档案。", "fields": "Tab label=健康档案；route=special；专区页面标题仍为发作性睡病专区。", "logic": "只修改导航和分组名称，保留原路由、页面功能及记录关联，不重建记录。二级页面不展示主导航。 本页不再展示睡眠辅助工具及其中三个入口；仅移除当前页面入口，不清空原有小憩、挑战或睡眠记录。"}];
PAGE_MODULES.mine = [{"title": "个人形象与账户状态", "description": "顶部显示眠宝形象、当前账户状态及用户ID，不再显示体验用户。", "fields": "state.userId：本地展示ID，首次访问我的页时生成MB前缀及12位字母数字串，并保存至现有账户状态；authStatus：active/signed-out/closed。正式版userId由账户服务返回。", "logic": "已有userId直接复用；缺失时补建并保存，不覆盖现有记录。页面输出按文本转义；刷新、退出再登录沿用同一ID，注销或清空后重新进入生成新ID。保存失败提示用户；ID仅为当前Demo展示标识，不作为真实身份验证。\n退出、注销及重新进入沿用现有流程。正式账号隔离、会话过期、跨设备同步、留存策略由账户服务定义。"}, {"title": "我的服务", "description": "我的服务分组仅显示个人资料，使用无副说明的紧凑入口。", "fields": "profile：个人资料路由。", "logic": "点击个人资料进入档案摘要二级页；不显示消息通知或我的记录入口。仅调整入口，不删除已有患者档案、消息或健康记录。通知偏好仍在设置页维护，本次不改变设置功能。"}, {"title": "设置", "description": "设置分组仅包含设置入口，不展示任务提醒设置入口。", "fields": "目标路由 accountSettings；settings.notificationEnabled；authStatus。", "logic": "点击设置进入账户设置二级页，保留通知偏好、用户协议、退出登录和注销账号功能。移除任务提醒设置入口不改写用药时间、小憩时长或现有任务数据。退出与注销沿用现有确认及数据处理流程；正式账号认证与数据留存规则待接口定义。"}];

// Archive medication cards 20261015
PAGE_MODULES.patientArchive = [{"title": "眠宝引导与确诊时间", "description": "展示眠宝建档引导；填写NT1阵发性睡病确诊时间，页面仍只采集确诊时间和当前用药两个业务字段。", "fields": "patientArchive.diagnosisDate：YYYY-MM-DD，必填；archiveFormDraft.diagnosisDate。", "logic": "校验日期真实有效且不晚于当前本地日期；未建档无默认日期，编辑时回填已保存日期。"}, {"title": "当前使用药物卡片", "description": "卡片按钮多选：盐酸替洛利生、莫达非尼、哌甲酯、其他药物；最后一项固定为暂无用药。选择其他药物时展开名称填写框。", "fields": "archiveDrugOptions[]：code、label；selectedDrugCodes[]：药物编码列表；otherDrugs：其他药物名称，选择other后必填；currentDrugs：由选择及其他名称生成的兼容文本，合计不超过500字。", "logic": "首次不预选，必须选择至少一项。暂无用药与所有药物互斥：选暂无清空其他勾选，选任何药物清除暂无；允许取消勾选后重选。不触发整页渲染，不清空确诊时间或左侧说明草稿。其他药物取消后保留本次表单文字，重新选中可继续填写；保存时只写入已选中的内容。\n卡片仅记录患者实际用药，不据此生成处方、剂量或用药任务。可配置药物名称，正式药物清单需业务与医学团队确认。选项名核对参考AASM发作性睡病指南（https://aasm.org/wp-content/uploads/2022/03/Treatment_Central_Disorders_Hypersomnolence_Guideline_at_a_Glance.pdf）；盐酸替洛利生中文名参考国家药监局公开资料（https://www.nmpa.gov.cn/directory/web/nmpa/images/1707039824076019627.pdf）。不表达各地区上市可及性。"}, {"title": "保存、返回与历史档案兼容", "description": "保存后回首页；从我的→个人资料进入时可回填修改，未保存返回不改写已存档案。", "fields": "patientArchive：diagnosisDate、currentDrugs、selectedDrugCodes、otherDrugs、createdAt、updatedAt；onboardingPending；archiveFormDraft。", "logic": "保存前校验日期、必选、暂无互斥和其他名称；失败保留勾选与文字、回滚旧档案，成功清除待建档标记。个人资料继续展示同一currentDrugs文本。旧文字档案按已知药名回填卡片，未知内容回填其他药物；旧暂无用药回填最后一项，不在进入页面时自动覆盖旧数据。保持二级页隐藏主导航。实际档案接口、业务时区与正式账号服务待接入。"}];

// 正式名称与眠宝引导 20261017
PAGE_MODULES.login = [{"title": "眠宝形象与立即登录", "description": "应用标题为发作性睡病之家，副文案为眠宝陪伴，记录每一天；展示眠宝形象及您好，我是眠宝，从了解自己开始，让我陪您把每一天记清楚。立即登录仅文字，保留协议查看。", "fields": "APP_NAME=发作性睡病之家；document.title同名。登录品牌主标题=APP_NAME；角色名=眠宝；route=login；state.authStatus；loginSession.phoneAuthorized。", "logic": "APP_NAME仅用于应用级品牌，不替换眠宝角色名或眠宝帮您功能名，不改存储键。手机号授权卡及协议欢迎语读取同一APP_NAME；登录跳转与授权处理沿用原逻辑。"}, {"title": "用户协议与隐私政策查看", "description": "用户主动点击链接才显示对应说明，点击我知道了关闭。 用户协议欢迎标题使用发作性睡病之家。", "fields": "sheet=loginTerms/loginPrivacy；文案由协议类型区分。", "logic": "仅供查看，不要求同意并继续，不写入新的协议确认时间；不作为登录的前置拦截。已有协议记录保留，不自动伪造确认。正式协议正文及正式授权规则待接入。"}, {"title": "手机号授权与登录结果", "description": "微信默认手机号授权样式卡片展示发作性睡病之家应用名称；拒绝或允许由用户操作。", "fields": "sheet=wechatPhone；authStatus=active；loginSession：phoneAuthorized、authorizedAt；onboardingPending。", "logic": "拒绝保留登录页；允许后写入登录状态并到达首页。仅允许在登录页且当前授权弹窗打开时确认；保存失败恢复原状态。无档案仍保留首次建档引导，有档案不重复提示。当前为授权样式 Demo，不接真实微信服务。"}];
PAGE_MODULES.home = [{"title": "应用名称与眠宝问候", "description": "首页主标题为发作性睡病之家，下方显示您好，我是眠宝，今天感觉怎么样？", "fields": "APP_NAME；顶部标题与问候为静态展示字段。", "logic": "只更新品牌和引导文案，不新增按钮、不改变晨起打卡、状态反馈或六项快捷服务。角色名眠宝与功能名眠宝帮您保留。"}, {"title": "首次登录建档引导", "description": "手机号授权后到达首页，无健康档案时展示带眠宝的建档提示弹窗；不显示右上角关闭按钮。 弹窗引导为让眠宝先认识您，先告诉我您的确诊时间和当前用药，我会帮您收好这份健康档案。", "fields": "onboardingPending、patientArchive；目标 patientArchive。", "logic": "点击建立档案进入两字段表单；点击稍后再说或遮罩关闭提示，已有档案不展示。刷新时未处理的提示保留；不影响首页其他服务。"}, {"title": "眠宝权益卡", "description": "根据商保状态和今日用药记录展示静态眠宝反馈，不展示任何状态操作按钮。", "fields": "当前字段补齐：insuranceStatus、meds[].day、homePreviewState。\n建议申请字段（待确认）：applicationId、applicationStatus、benefitStatus、updatedAt、rejectReason。", "logic": "homeStatus计算未领取、审核中、已领取未记录、已领取已记录四种展示态；反馈区域统一使用div，不绑定点击、跳转或弹窗。未记录文案为“今天的用药还未记录”，不再提示在本卡片操作。点击眠宝仍可切换展示态，不改写申请或用药数据。患者福利、用药记录等功能沿用NT1专区原有入口。\n今日任务区域已移除，不展示任务卡片或首页小憩倒计时；不清空已有业务数据。正式申请状态与权益文案映射仍待业务确认。"}, {"title": "首页滚动 Banner", "description": "晨起状态与眠宝权益卡之后展示三张固定推荐卡片，分别进入健康记录、眠宝帮您和知识中心；支持自动轮播、箭头、指示点、横向滑动；不显示暂停按钮。", "fields": "homeBanners[]：title、text、action、target、theme；bannerStates.home：index。", "logic": "页面顺序为顶部问候→晨起状态和眠宝权益卡→Banner→NT1专区。轮播每 5 秒循环；离开页面清除计时器，页面隐藏、轮播内有焦点或系统要求减少动态时暂停。仅更新轮播区域，不清空左侧编辑输入。"}, {"title": "NT1专区", "description": "区域标题为NT1专区。六个入口：病程记录、药房地图、线上购药、患者福利、用药记录和我的专员。患者福利按钮右上方显示申请状态角标，默认未申请。", "fields": "journey、pharmacy、shop、payment、medReminder、specialist。\n角标来自paymentSummary().label；insuranceStatus=unclaimed/reviewing/applied/claimed/rejected。", "logic": "语音病历与病程记录合并，仅保留一个病程记录入口；该页支持图片、拍照和长按语音。其余入口保留原逻辑。\n未申请显示未申请，reviewing显示审核中；applied/claimed/rejected沿用既有三态概览映射为已申请，具体已申请含义仍待业务定义。角标随状态重绘更新，不额外保存状态，不改变按钮目标。"}, {"title": "病程记录快捷入口", "description": "进入病程记录后，先从底部弹窗选择语音或图片方式，再进入对应录入页；草稿和历史按已选方式恢复。", "fields": "journey/journeyHistory；journeyRecords[]、journeyDrafts；旧 voiceCases/documentCases 兼容读取。", "logic": "新建选择语音/图片，取消返回来源；有内容可切换方式补充而不丢资料。未完成记录可恢复草稿；旧图片与语音记录保留在统一历史。当前提取为Demo效果，保存后不自动生成猝倒事件或服药任务。"}, {"title": "状态打卡", "description": "四档状态选择：精神饱满/有些疲惫/需要小睡/状态不佳；\n选择后下方对应文案变更；", "fields": "moods[本地日期]：四档状态之一。\n建议正式字段（待确认）：userId、recordDate、moodCode、createdAt、updatedAt；recordDate 按选定业务时区生成。", "logic": "同日只能提交一次；已记录时禁用四个选项。\n\n【B02/B03｜现状】四档仅更新“今天的感受”文字；权益主文案由支付和服药记录决定。当前同日一次，不可修改。\n【建议规则（待确认）】晨起记录按 userId + recordDate 唯一；误选通过“修改当日状态”覆盖原记录而非新增，保留修改时间；未选择时显示引导，已选择时显示选中项。跨日重新计算日期及可选状态。\n【待确认】是否开放修改；四档对应反馈文案与形象配置；晨起反馈与权益信息的排列关系；日期统一北京时间还是用户时区。未确认前不把晨起状态当作疾病判断。"}];
PAGE_MODULES.patientArchive = [{"title": "眠宝引导与确诊时间", "description": "建档页显示眠宝形象和先让眠宝了解您引导：填写确诊时间，选择当前使用的药物，我会陪您一起记录与回顾。仍只采集原有两个业务字段。", "fields": "patientArchive.diagnosisDate：YYYY-MM-DD，必填；archiveFormDraft.diagnosisDate。", "logic": "校验日期真实有效且不晚于当前本地日期；未建档无默认日期，编辑时回填已保存日期。"}, {"title": "当前使用药物卡片", "description": "卡片按钮多选：盐酸替洛利生、莫达非尼、哌甲酯、其他药物；最后一项固定为暂无用药。选择其他药物时展开名称填写框。", "fields": "archiveDrugOptions[]：code、label；selectedDrugCodes[]：药物编码列表；otherDrugs：其他药物名称，选择other后必填；currentDrugs：由选择及其他名称生成的兼容文本，合计不超过500字。", "logic": "首次不预选，必须选择至少一项。暂无用药与所有药物互斥：选暂无清空其他勾选，选任何药物清除暂无；允许取消勾选后重选。不触发整页渲染，不清空确诊时间或左侧说明草稿。其他药物取消后保留本次表单文字，重新选中可继续填写；保存时只写入已选中的内容。\n卡片仅记录患者实际用药，不据此生成处方、剂量或用药任务。可配置药物名称，正式药物清单需业务与医学团队确认。选项名核对参考AASM发作性睡病指南（https://aasm.org/wp-content/uploads/2022/03/Treatment_Central_Disorders_Hypersomnolence_Guideline_at_a_Glance.pdf）；盐酸替洛利生中文名参考国家药监局公开资料（https://www.nmpa.gov.cn/directory/web/nmpa/images/1707039824076019627.pdf）。不表达各地区上市可及性。"}, {"title": "保存、返回与历史档案兼容", "description": "保存后回首页；从我的→个人资料进入时可回填修改，未保存返回不改写已存档案。", "fields": "patientArchive：diagnosisDate、currentDrugs、selectedDrugCodes、otherDrugs、createdAt、updatedAt；onboardingPending；archiveFormDraft。", "logic": "保存前校验日期、必选、暂无互斥和其他名称；失败保留勾选与文字、回滚旧档案，成功清除待建档标记。个人资料继续展示同一currentDrugs文本。旧文字档案按已知药名回填卡片，未知内容回填其他药物；旧暂无用药回填最后一项，不在进入页面时自动覆盖旧数据。保持二级页隐藏主导航。实际档案接口、业务时区与正式账号服务待接入。"}];
PAGE_MODULES.journey = [{"title": "记录方式选择与页面结构", "description": "新建且无草稿时先展示底部选择弹窗，选择语音记录或上传图片记录后进入对应页面；可查看历史记录。 选择弹窗用眠宝陪您记录这一次引导，提示说一说或上传资料，整理后核对。", "fields": "route=journey；route.caseId；journeyUi.mode=voice/image/null；modePickerOpen；record.inputMode；journeyHistory；journeyUi.key/record/dirty。", "logic": "首次新建自动弹出选择；点击暂不记录、遮罩或Escape返回来源页。选择语音显示长按按钮及语音说明；选择图片显示相册/拍照按钮和图片说明。主导航不在二级页展示。选择本身不产生业务记录；无内容刷新后重新选择。已有记录或有效草稿直接按inputMode恢复；旧记录按图片/语音来源推断，不再强制选择。"}, {"title": "切换方式与混合资料", "description": "点击切换记录方式再次打开底部弹窗，可为同一经历补充另一种来源。", "fields": "journeyUi.mode/modePickerOpen；record.inputMode、images、originalText、facts、visitInfo；journeyUi.dirty。", "logic": "切换只改变当前录入控件，不清空原图、原话、已提取字段或人工修改。切换弹窗取消/遮罩/Escape回到原方式；语音/提取处理中禁止切换。草稿与保存记录保留当前方式，旧数据兼容回看。保存后再记一条重新选择方式。"}, {"title": "图片选择、拍照与原图预览", "description": "从相册选择支持多选；拍照使用设备图片拍摄入口；上传后自动整理，原图可放大或移除。 图片页以把就诊、用药资料交给我，整理后请您核对引导。", "fields": "record.images[]：id、name、source(upload/camera)、dataUrl；journeyUpload.multiple；journeyCamera.capture=environment。", "logic": "最多4张、单张≤10MB，支持JPEG/PNG/WebP。数量/格式/大小校验后解码，最长边1280px，JPEG质量0.78；保存压缩图片。取消选择不改记录，批次处理失败不部分追加。设备决定摄像头或文件选择行为。移除图片保留已填写信息并提示核对；无任何来源时不能保存。"}, {"title": "图片信息提取与结果合并", "description": "上传后展示loading，结果保留原图，关键信息仅回显时间和描述。", "fields": "journeyUi.phase=uploading/extracting/idle；record.facts、visitInfo、extractedAt；journeyProvider().extract({kind,text,images,referenceAt,signal})。", "logic": "本次继续采用用户已确认的 Demo：没有真实OCR或大模型调用。当前为既有示例服务，不视为上传材料的真实识别结果；用户按本次意见移除提取示例标签。图片补全尚空的核心字段，就诊用药字段保留在内部原结果中，不再逐项展示；不覆盖用户手动修改的字段。原图不因模型失败而删除。"}, {"title": "长按语音与微信样式弹窗", "description": "按住显示麦克风、波形和时长；上滑进入取消状态，松开取消或结束。 语音页提示什么时候、有什么表现、出现几次，都可以慢慢说。", "fields": "phase=recording；holdStart、holdY、cancelVoice、holdTimer；voiceReferenceAt、voiceDuration；上滑阈值70px。", "logic": "按住至少500ms，太短提示重新按住；最长60秒自动结束。上滑70px以上松手取消，移回可继续；指针取消、失去捕获、Escape、窗口失焦或切到后台均取消，保留已有内容。触屏阻止滚动与系统长按菜单；支持空格/回车长按及辅助技术激活。Demo展示录音交互和固定转写，不采集真实麦克风或音频。"}, {"title": "语音转文字与模型等待弹窗", "description": "松开后先显示转换文字，再显示整理信息的 loading 弹窗；可取消等待。 等待文案采用眠宝第一人称说明正在准备图片、转换文字或整理时间和描述。", "fields": "phase=transcribing/extracting；controller、job、retryKind、retryReanalyse；服务接口 transcribe/extract；超时20秒。", "logic": "两段异步任务均等待完成后才回显；取消或离页后晚到结果不能覆盖当前页。超时或失败关闭弹窗，保留已有图片、已完成转写文字和旧字段，提供重新整理或手动填写。转写本身未完成时需要重新记录或重试；正式版需接录音/ASR并保留音频，当前Demo没有实际音频文件。"}, {"title": "原始资料与时间、描述", "description": "保留原始图片和可修正的语音识别原文。关键信息不显示提取示例/手动核对标签，仅显示时间和描述两个可编辑字段。 核对区增加眠宝已经整理好了，请核对时间和描述，确认后再保存。", "fields": "facts.date：时间（YYYY-MM-DD）；record.description：描述，最多2000字；originalText/originalTranscript/images：原始资料；旧facts.timeOriginal/period/symptoms/count与visitInfo保留内部兼容。", "logic": "时间和描述沿用红色关键内容样式，均可修改；时间校验有效且不晚于当天，未提取到日期可留空。描述初次由症状及次数等提取结果合并，图片优先使用材料摘要；缺失不编造。人工修改description加入edited/userEditedFields，后续图片/语音整理不覆盖人工描述。修正语音原文后重新整理，若未人工改过描述则按新结果更新。相对日期仍以首次语音referenceAt与北京时间为锚点。旧记录无description时，读取时组合已有摘要/症状/次数回显，不删除旧字段，不自动新增记录。"}, {"title": "多来源互补与原结果保留", "description": "同一记录可补充图片和语音；界面简化为时间和描述，不再展开医院、科室、药品等补充字段。", "fields": "record.description；facts、visitInfo；journeyUi.edited；record.userEditedFields；images、originalText、voiceSegments。", "logic": "模式切换和新增来源不删除原图、原话与既有内部提取字段。模型结果只更新未人工修改的数据；描述一旦人工修改，后续整理保留人工版本。医院/科室/药品等旧信息仍保存在记录内部，本次仅收起其编辑界面。不会据此新增诊断或用药建议。"}, {"title": "草稿、保存与历史兼容", "description": "未完成内容保存为草稿，返回/刷新可恢复；确认保存后禁用重复保存，可再次新建。旧图片与语音记录统一可见。", "fields": "state.journeyRecords[]；state.journeyDrafts 按new/recordId保存草稿；兼容 journeyDraft；record：id、createdAt、updatedAt、referenceAt、timeZone、images、originalText、originalTranscript、voiceSegments、facts、visitInfo、extractedAt、extractionSource、optimizedText、userEditedFields、legacy。；needsExtraction：新增或修正来源后需要重新整理；manualReview：手动核对状态。\nrecord.description与userEditedFields中的description一并保存；历史卡片和optimizedText读取核对后的描述。", "logic": "草稿输入300ms防抖保存，离页及时保存；草稿不计入历史数量。保存失败恢复原数组并保留修改，可重试；草稿保存失败离页提示真实丢失风险。首次保存新增，之后按同一ID更新，保留创建时间。旧voiceCases/documentCases通过voice:/image:前缀兼容映射；更新写新数组并按ID去重，旧数据不删除。记录与草稿共用主应用存储，注销/清除主存储同时清理。不自动写入猝倒趋势或今日用药任务。 未完成提取的草稿刷新后提供继续整理信息入口，不自动重复请求。确认保存视为已核对，不继续显示待整理状态。"}];
PAGE_MODULES.rights = [{"title": "知识中心导航与眠宝引导", "description": "页面和导航保留知识中心功能名，顶部眠宝引导为和眠宝一起读懂健康知识，想了解什么？先选个分类，我陪您慢慢看。", "fields": "导航 label=知识中心；route=rights（保留原路由键）；首页 homeBanners[2].target=rights。", "logic": "权益中心页面整体替换为知识中心，不展示创新支付状态卡、保障服务卡或 Banner。首页患者福利及眠宝帮您中已有申请功能保留；标题更名不改变支付数据。"}, {"title": "文章分类筛选", "description": "显示全部、就医准备、日常记录、用药记录、援助服务分类，可横向滚动。", "fields": "knowledgeCategories 由文章分类去重；knowledgeFilter；knowledgeArticles[].category。", "logic": "默认全部，点击分类只更新筛选按钮和文章列表，不重绘整页或清空左侧编辑内容；分类及列表位置在当前会话保留，刷新回到全部。"}, {"title": "患教文章列表", "description": "文章卡片仅显示封面、分类、标题和年月日格式的发布日期；不显示副标题或箭头，整张卡片均可点击。", "fields": "knowledgeArticles[]：id、category、title、publishedAt(YYYY-MM-DD)、summary、read、icon、theme、sections[][]；当前6篇本地文章。knowledgePublishDate 将日期格式化为 YYYY年M月D日。", "logic": "按配置顺序展示，分类过滤与篇数使用同一结果；无匹配显示空态。列表不展示summary或阅读时长；summary仅保留在详情。Demo示例发布日期统一配置为2026-10-15，不能随访问日期变化；正式发布日期由内容服务提供，不使用阅读时长替代。缺少发布日期时不显示日期，不影响进入详情。"}, {"title": "详情跳转与回到列表", "description": "点击文章以唯一 ID 进入文章详情，返回列表可继续浏览。", "fields": "route=articleDetail；route.articleId；knowledgeScrollTop。", "logic": "进入详情前保存列表滚动位置；返回读取同一目录并恢复当前分类和位置，不创建新会话或患者记录。详情为二级页，隐藏首页功能栏。"}];
PAGE_MODULES.ai = [{"title": "眠宝欢迎与咨询", "description": "显示眠宝帮您功能标题及发作性睡病之家品牌副标。眠宝欢迎区提示在这里，您可以了解知识、记录近况，想问什么，慢慢告诉我吧；保留热门问题和自由咨询。", "fields": "服务独立状态 mianbao-integrated-service-v1；sessions[]、messages[]。", "logic": "欢迎区仅展示眠宝形象与介绍，点击问问眠宝进入咨询；不展示或写入每日状态记录。会话超过 3 天未互动新建，历史保留近 12 个月；AI 为本地规则匹配，医学与政策内容待正式审核。该模块数据不改写首页、专病管理、权益中心与我的现有记录。 应用名是发作性睡病之家，眠宝是陪伴角色，眠宝帮您是助手功能名；不更名路由、存储键或福利计划。"}, {"title": "创新支付、入组与援助申请", "description": "展示入组、福利订单和直付/后报销进度；在会话中逐步完善资料、上传材料、核对提交，支持暂停、恢复、重新填写及驳回补件。", "fields": "enrollment、type、code、patient、orders[]、aidDrafts 与会话 careFlows；材料图片本地保存。", "logic": "保留源模块的状态字典与订单过滤：20 区分药房审核阶段、21 过滤；后报销需处方与发票，直付含用药数量。申请提交为本地流程，未接保险/审核/理赔接口；不改变首页患者福利的状态。"}, {"title": "病历夹与用药记录", "description": "聊天中记录病程文字、录制语音、上传图片；支持时间线、类型筛选、音频回放、图片放大和用药记录。", "fields": "IndexedDB mianbao-integrated-care-records-v1 的 records、media；记录时间、文字、媒体、药品、用药状态、备注。", "logic": "语音为录音与回放，不含语音转文字；每段最长 2 分钟，图片每条最多 4 张，单文件最多 10 MB，图片压缩后保存。记录时间不能在未来，保存前需停止录音；用药状态含已服用/漏服/暂停，新增记录不提供医学建议。"}, {"title": "健康科普", "description": "先在聊天中展示三篇推荐文章；查看更多展开六篇文章及分类，支持全文阅读、收起与展开。", "fields": "源模块 articles[]、articleFilter、articleId 与消息 kind=articles/appPanel。", "logic": "所有文章操作保持在眠宝会话内；内容为记录与资料整理说明，正式医学内容和发布审核接口待接入。"}, {"title": "客服与我的服务", "description": "真人客服入口；头像展开患者资料、历史会话和福利关爱记录。", "fields": "patient、sessions[]、orders[]；历史会话分页；申请人姓名打码。reports[] 仅保留旧数据兼容，不新增事件记录。", "logic": "移除疑似不良事件记录入口、确认表单及保存流程；用药相关咨询仍可回答一般说明并引导联系医生/药师，不生成事件报告。旧记录保留，不因功能移除而擦除数据。"}, {"title": "会话快捷操作与状态设置", "description": "发起会话后，输入区上方展示可横向滑动的创新支付、记录病程、用药记录、真人客服；状态按钮保留源模块场景切换和数据重置。", "fields": "activeSession、view、conversationActions；入组/支付/订单状态控件。", "logic": "首屏与空会话不显示快捷按钮；状态设置只更新本服务模块。清空聊天保留说明、病历、用药与订单；重置仅清理本服务模块数据。宿主左侧说明及右侧修改意见沿用原保存机制。"}];
PAGE_MODULES.mine = [{"title": "个人形象与账户状态", "description": "顶部显示眠宝形象、当前账户状态及用户ID，不再显示体验用户。 问候文案使用眠宝陪您，记录每一天，保留原用户ID。", "fields": "state.userId：本地展示ID，首次访问我的页时生成MB前缀及12位字母数字串，并保存至现有账户状态；authStatus：active/signed-out/closed。正式版userId由账户服务返回。", "logic": "已有userId直接复用；缺失时补建并保存，不覆盖现有记录。页面输出按文本转义；刷新、退出再登录沿用同一ID，注销或清空后重新进入生成新ID。保存失败提示用户；ID仅为当前Demo展示标识，不作为真实身份验证。\n退出、注销及重新进入沿用现有流程。正式账号隔离、会话过期、跨设备同步、留存策略由账户服务定义。"}, {"title": "我的服务", "description": "我的服务分组仅显示个人资料，使用无副说明的紧凑入口。", "fields": "profile：个人资料路由。", "logic": "点击个人资料进入档案摘要二级页；不显示消息通知或我的记录入口。仅调整入口，不删除已有患者档案、消息或健康记录。通知偏好仍在设置页维护，本次不改变设置功能。"}, {"title": "设置", "description": "设置分组仅包含设置入口，不展示任务提醒设置入口。", "fields": "目标路由 accountSettings；settings.notificationEnabled；authStatus。", "logic": "点击设置进入账户设置二级页，保留通知偏好、用户协议、退出登录和注销账号功能。移除任务提醒设置入口不改写用药时间、小憩时长或现有任务数据。退出与注销沿用现有确认及数据处理流程；正式账号认证与数据留存规则待接口定义。"}];

