PAGE_MODULES.ai = [{"title": "眠宝欢迎与咨询", "description": "显示眠宝帮您功能标题及发作性睡病之家品牌副标。眠宝欢迎区提示在这里，您可以了解知识、记录近况，想问什么，慢慢告诉我吧；保留热门问题和自由咨询。", "fields": "服务独立状态 mianbao-integrated-service-v1；sessions[]、messages[]。", "logic": "欢迎区仅展示眠宝形象与介绍，点击问问眠宝进入咨询；不展示或写入每日状态记录。会话超过 3 天未互动新建，历史保留近 12 个月；AI 为本地规则匹配，医学与政策内容待正式审核。该模块数据不改写首页、专病管理、权益中心与我的现有记录。 应用名是发作性睡病之家，眠宝是陪伴角色，眠宝帮您是助手功能名；不更名路由、存储键或福利计划。"}, {"title": "创新支付、入组与援助申请", "description": "展示入组、福利订单和直付/后报销进度；在会话中逐步完善资料、上传材料、核对提交，支持暂停、恢复、重新填写及驳回补件。", "fields": "enrollment、type、code、patient、orders[]、aidDrafts 与会话 careFlows；材料图片本地保存。", "logic": "保留源模块的状态字典与订单过滤：20 区分药房审核阶段、21 过滤；后报销需处方与发票，直付含用药数量。申请提交为本地流程，未接保险/审核/理赔接口；不改变首页患者福利的状态。"}, {"title": "病历夹与用药记录", "description": "聊天中记录病程文字、录制语音、上传图片；支持时间线、类型筛选、音频回放、图片放大和用药记录。", "fields": "IndexedDB mianbao-integrated-care-records-v1 的 records、media；记录时间、文字、媒体、药品、用药状态、备注。", "logic": "语音为录音与回放，不含语音转文字；每段最长 2 分钟，图片每条最多 4 张，单文件最多 10 MB，图片压缩后保存。记录时间不能在未来，保存前需停止录音；用药状态含已服用/漏服/暂停，新增记录不提供医学建议。"}, {"title": "健康科普", "description": "先在聊天中展示三篇推荐文章；查看更多展开六篇文章及分类，支持全文阅读、收起与展开。", "fields": "源模块 articles[]、articleFilter、articleId 与消息 kind=articles/appPanel。", "logic": "所有文章操作保持在眠宝会话内；内容为记录与资料整理说明，正式医学内容和发布审核接口待接入。"}, {"title": "客服与我的服务", "description": "真人客服入口；头像展开患者资料、历史会话和福利关爱记录。", "fields": "patient、sessions[]、orders[]；历史会话分页；申请人姓名打码。reports[] 仅保留旧数据兼容，不新增事件记录。", "logic": "移除疑似不良事件记录入口、确认表单及保存流程；用药相关咨询仍可回答一般说明并引导联系医生/药师，不生成事件报告。旧记录保留，不因功能移除而擦除数据。"}, {"title": "会话快捷操作与状态设置", "description": "发起会话后，输入区上方展示可横向滑动的创新支付、记录病程、用药记录、真人客服；状态按钮保留源模块场景切换和数据重置。", "fields": "activeSession、view、conversationActions；入组/支付/订单状态控件。", "logic": "首屏与空会话不显示快捷按钮；状态设置只更新本服务模块。清空聊天保留说明、病历、用药与订单；重置仅清理本服务模块数据。宿主左侧说明及右侧修改意见沿用原保存机制。"}, {"title": "左侧说明工具：清空聊天记录", "description": "各页面左侧说明下方均展示清空聊天记录按钮，说明编辑状态也可使用。点击清空眠宝帮您中的历史会话和当前对话，回到助手欢迎状态。", "fields": "mianbao-integrated-service-v1.sessions[]；activeSession、typing、replyTimer；chatHistoryClearing；子模块window.clearMianbaoChatHistory()。", "logic": "全局按钮调用眠宝已有会话清理逻辑，不改变当前主页面路由或左侧/右侧未保存内容。若助手未打开，临时加载同一服务执行清理，完成后移除临时载体；助手已打开时同步清空界面并关闭历史详情。清除等待中的回复及输入，不重新生成示例历史；刷新或再次进入仍为空。\n已保存的病程、用药、图片语音附件、患者资料及福利订单不清除；援助申请草稿沿用既有保留逻辑。重复点击期间禁用按钮；保存失败恢复原会话状态并提示，不显示虚假成功。此按钮属于左侧说明工具，不加入患者端功能导航。"}];

