PAGE_MODULES.ai = [{"title": "眠宝欢迎与咨询", "description": "显示眠宝帮您功能标题及发作性睡病之家品牌副标。眠宝欢迎区提示在这里，您可以了解知识、记录近况，想问什么，慢慢告诉我吧；保留热门问题和自由咨询。", "fields": "服务独立状态 mianbao-integrated-service-v1；sessions[]、messages[]。", "logic": "欢迎区仅展示眠宝形象与介绍，点击问问眠宝进入咨询；不展示或写入每日状态记录。会话超过 3 天未互动新建，历史保留近 12 个月；AI 为本地规则匹配，医学与政策内容待正式审核。该模块数据不改写首页、专病管理、权益中心与我的现有记录。 应用名是发作性睡病之家，眠宝是陪伴角色，眠宝帮您是助手功能名；不更名路由、存储键或福利计划。"}, {"title": "创新支付、入组与援助申请", "description": "展示入组、福利订单和直付/后报销进度；在会话中逐步完善资料、上传材料、核对提交，支持暂停、恢复、重新填写及驳回补件。", "fields": "enrollment、type、code、patient、orders[]、aidDrafts 与会话 careFlows；材料图片本地保存。", "logic": "保留源模块的状态字典与订单过滤：20 区分药房审核阶段、21 过滤；后报销需处方与发票，直付含用药数量。申请提交为本地流程，未接保险/审核/理赔接口；不改变首页患者福利的状态。"}, {"title": "病历夹与用药记录", "description": "病历夹保留已有病程、用药及媒体回看；记录病程按钮统一从底部打开与首页相同的图片/语音病程模块，支持核对后保存。", "fields": "IndexedDB mianbao-integrated-care-records-v1 的 records、media；记录时间、文字、媒体、药品、用药状态、备注。 nativeJourneyId为主病程记录ID；镜像recordDate为提取日期，when/created为实际创建时间。", "logic": "语音为录音与回放，不含语音转文字；每段最长 2 分钟，图片每条最多 4 张，单文件最多 10 MB，图片压缩后保存。记录时间不能在未来，保存前需停止录音；用药状态含已服用/漏服/暂停，新增记录不提供医学建议。 新弹窗复用主应用journey模块，主记录仍写入mianbao-prototype-v1.journeyRecords；保存后向助手IndexedDB records同步一份带nativeJourneyId的列表镜像，图片同步为media附件。助手内修改此类记录会重新打开同一主记录，不另建副本。关闭弹窗保留已有草稿；顶部功能栏及其他页面样式不变。"}, {"title": "健康科普", "description": "先在聊天中展示三篇推荐文章；查看更多展开六篇文章及分类，支持全文阅读、收起与展开。", "fields": "源模块 articles[]、articleFilter、articleId 与消息 kind=articles/appPanel。", "logic": "所有文章操作保持在眠宝会话内；内容为记录与资料整理说明，正式医学内容和发布审核接口待接入。"}, {"title": "客服与我的服务", "description": "真人客服入口；头像展开患者资料、历史会话和福利关爱记录。", "fields": "patient、sessions[]、orders[]；历史会话分页；申请人姓名打码。reports[] 仅保留旧数据兼容，不新增事件记录。", "logic": "移除疑似不良事件记录入口、确认表单及保存流程；用药相关咨询仍可回答一般说明并引导联系医生/药师，不生成事件报告。旧记录保留，不因功能移除而擦除数据。"}, {"title": "会话快捷操作与状态设置", "description": "会话开始后显示横向创新支付、记录病程、用药记录、真人客服按钮；记录病程打开底部记录弹窗，其他服务保持既有入口。", "fields": "activeSession、view、conversationActions；入组/支付/订单状态控件。", "logic": "首屏与空会话不显示快捷按钮；状态设置只更新本服务模块。清空聊天保留说明、病历、用药与订单；重置仅清理本服务模块数据。宿主左侧说明及右侧修改意见沿用原保存机制。 图片或语音示例发送也视为发起会话，因而显示快捷服务。"}, {"title": "左侧说明工具：清空聊天记录", "description": "各页面左侧说明下方均展示清空聊天记录按钮，说明编辑状态也可使用。点击清空眠宝帮您中的历史会话和当前对话，回到助手欢迎状态。", "fields": "mianbao-integrated-service-v1.sessions[]；activeSession、typing、replyTimer；chatHistoryClearing；子模块window.clearMianbaoChatHistory()。", "logic": "全局按钮调用眠宝已有会话清理逻辑，不改变当前主页面路由或左侧/右侧未保存内容。若助手未打开，临时加载同一服务执行清理，完成后移除临时载体；助手已打开时同步清空界面并关闭历史详情。清除等待中的回复及输入，不重新生成示例历史；刷新或再次进入仍为空。\n已保存的病程、用药、图片语音附件、患者资料及福利订单不清除；援助申请草稿沿用既有保留逻辑。重复点击期间禁用按钮；保存失败恢复原会话状态并提示，不显示虚假成功。此按钮属于左侧说明工具，不加入患者端功能导航。"}, {"title": "微信形式的输入栏与示例发送", "description": "文字输入左侧增加语音按钮，右侧增加图片按钮，保留文字发送。点击语音或图片直接发送对应示例消息，无需授权麦克风或选择真实文件。", "fields": "assistantVoiceButton、assistantImageButton；sessions[].messages[]新增demoChatVoice/demoChatImage；每条有id、at，语音含text，图片含src。", "logic": "语音示例显示8秒气泡及识别文字；图片示例显示处方缩略图。发送仅写入会话，不立即新增申请或病程。保留原文字输入和流程内上传能力；正在回复/保存时提示等待，避免重复交错处理。示例语音播放只展示动态效果，不调用录音或识别服务。"}, {"title": "图片发送后的创新支付确认", "description": "图片消息后在聊天内显示眠宝确认卡片，询问是否需要发起新的创新支付；可选择是、发起申请或暂不需要。", "fields": "demoMediaIntent.intent=payment；sourceMessageId；status=pending/opened/declined；pendingDraft.rx引用该示例图片。", "logic": "暂不需要只关闭本次意图，不新增申请。是先校验入组和正在审核的申请限制，再进入助手内部创新支付申请页；图片预填为处方示例，可修改或补充材料。进入页面不等于提交，只有完成材料校验并确认提交后才创建订单。返回保留会话，卡片可继续填写；重复提交受页面状态和既有审核中规则限制。保存失败回滚订单、保留填写内容并提示重试。"}, {"title": "语音发送后的病程确认", "description": "语音消息后在聊天内询问是否将刚刚的信息记录到病程；确认后新增一条可回看的病程，拒绝不新增业务记录。", "fields": "demoMediaIntent.intent=journey；recordId=assistant-voice-消息ID；status=pending/saving/saved/declined；nativeSaved、error；原始语音示例文字和at固定保存。", "logic": "确认时以消息ID生成稳定病程ID，调用宿主saveVoiceRecord；保留原文，并沿用既有提取逻辑生成时间和描述。主记录成功后同步助手病历夹镜像。重复点击、刷新或重试按相同ID去重，不覆盖已人工编辑记录；成功卡片提供查看病程。主记录保存失败不新增，展示错误并允许重试；主记录已存但镜像失败时提示重试同步，不重复建档。暂不需要不写入病程或猝倒/用药统计。"}, {"title": "底部弹窗复用首页病程模块", "description": "点击记录病程从底部拉起弹窗，内部呈现首页同一病程模块：选择语音/图片、整理加载、原始资料、时间和描述核对及保存。", "fields": "assistantWorkflowDialog(mode=journey)；assistantJourneyFrame；assistantJourney=1嵌入参数；mianbao-journey-saved/close消息；mianbaoJourneyHost桥接。", "logic": "仅在助手触发的嵌入模式隐藏重复的说明栏、手机状态栏及主导航；普通首页与其他页面布局不变。接收消息必须匹配同源及当前嵌入窗口。顶部返回/关闭回到原会话，未完成资料沿用原草稿保存；保存后刷新宿主病程数据并同步助手病历夹，展示已保存卡片。查看或修改同一记录使用caseId回填原记录，不重新提取、不重复新增。"}];

// 助手状态tag、图片三选项和用药弹窗 20261019
PAGE_MODULES.ai = [{"title": "眠宝欢迎与咨询", "description": "保留眠宝帮您标题、发作性睡病之家品牌副标、眠宝形象和问候；欢迎卡片移除发作性睡病之家 · 眠宝陪伴这一行。保留热门问题与自由咨询。", "fields": "服务独立状态 mianbao-integrated-service-v1；sessions[]、messages[]。", "logic": "欢迎区仅展示眠宝形象与介绍，点击问问眠宝进入咨询；不展示或写入每日状态记录。会话超过 3 天未互动新建，历史保留近 12 个月；AI 为本地规则匹配，医学与政策内容待正式审核。该模块数据不改写首页、专病管理、权益中心与我的现有记录。 应用名是发作性睡病之家，眠宝是陪伴角色，眠宝帮您是助手功能名；不更名路由、存储键或福利计划。"}, {"title": "创新支付、入组与援助申请", "description": "展示入组、福利订单和直付/后报销进度；在会话中逐步完善资料、上传材料、核对提交，支持暂停、恢复、重新填写及驳回补件。 首屏创新支付入口卡片增加状态tag，与会话上方创新支付快捷入口使用同一状态汇总。", "fields": "enrollment、type、code、patient、orders[]、aidDrafts 与会话 careFlows；材料图片本地保存。 assistantPaymentMeta()由state.enrollment/type/code计算tag，两个入口不额外保存标签。", "logic": "保留源模块的状态字典与订单过滤：20 区分药房审核阶段、21 过滤；后报销需处方与发票，直付含用药数量。申请提交为本地流程，未接保险/审核/理赔接口；不改变首页患者福利的状态。 tag沿用当前助手既有入组/审核/通过/完成状态映射，申请提交后随状态重绘；本次不改变首页患者福利的状态映射。"}, {"title": "病历夹与用药记录", "description": "病历夹保留已有病程、用药及媒体回看；记录病程按钮复用首页病程模块，用药记录按钮复用首页同名入口当前对应的功能。", "fields": "IndexedDB mianbao-integrated-care-records-v1 的 records、media；记录时间、文字、媒体、药品、用药状态、备注。 nativeJourneyId为主病程记录ID；镜像recordDate为提取日期，when/created为实际创建时间。", "logic": "语音为录音与回放，不含语音转文字；每段最长 2 分钟，图片每条最多 4 张，单文件最多 10 MB，图片压缩后保存。记录时间不能在未来，保存前需停止录音；用药状态含已服用/漏服/暂停，新增记录不提供医学建议。 新弹窗复用主应用journey模块，主记录仍写入mianbao-prototype-v1.journeyRecords；保存后向助手IndexedDB records同步一份带nativeJourneyId的列表镜像，图片同步为media附件。助手内修改此类记录会重新打开同一主记录，不另建副本。关闭弹窗保留已有草稿；顶部功能栏及其他页面样式不变。"}, {"title": "健康科普", "description": "先在聊天中展示三篇推荐文章；查看更多展开六篇文章及分类，支持全文阅读、收起与展开。", "fields": "源模块 articles[]、articleFilter、articleId 与消息 kind=articles/appPanel。", "logic": "所有文章操作保持在眠宝会话内；内容为记录与资料整理说明，正式医学内容和发布审核接口待接入。"}, {"title": "客服与我的服务", "description": "真人客服入口；头像展开患者资料、历史会话和福利关爱记录。", "fields": "patient、sessions[]、orders[]；历史会话分页；申请人姓名打码。reports[] 仅保留旧数据兼容，不新增事件记录。", "logic": "移除疑似不良事件记录入口、确认表单及保存流程；用药相关咨询仍可回答一般说明并引导联系医生/药师，不生成事件报告。旧记录保留，不因功能移除而擦除数据。"}, {"title": "会话快捷操作", "description": "会话开始后显示横向创新支付、记录病程、用药记录、真人客服按钮；记录病程与用药记录均打开底部复用模块。移除顶部状态按钮。", "fields": "activeSession、view、conversationActions；入组/支付/订单状态控件。", "logic": "图片或语音示例发送均可发起会话并显示快捷服务。顶部不再提供患者手动切换服务状态的按钮；保留既有申请状态和业务数据。记录病程进入journey嵌入模式；用药记录进入首页同一入口当前对应的medReminder嵌入模式，其余服务入口保持原逻辑。"}, {"title": "左侧说明工具：清空聊天记录", "description": "各页面左侧说明下方均展示清空聊天记录按钮，说明编辑状态也可使用。点击清空眠宝帮您中的历史会话和当前对话，回到助手欢迎状态。", "fields": "mianbao-integrated-service-v1.sessions[]；activeSession、typing、replyTimer；chatHistoryClearing；子模块window.clearMianbaoChatHistory()。", "logic": "全局按钮调用眠宝已有会话清理逻辑，不改变当前主页面路由或左侧/右侧未保存内容。若助手未打开，临时加载同一服务执行清理，完成后移除临时载体；助手已打开时同步清空界面并关闭历史详情。清除等待中的回复及输入，不重新生成示例历史；刷新或再次进入仍为空。\n已保存的病程、用药、图片语音附件、患者资料及福利订单不清除；援助申请草稿沿用既有保留逻辑。重复点击期间禁用按钮；保存失败恢复原会话状态并提示，不显示虚假成功。此按钮属于左侧说明工具，不加入患者端功能导航。"}, {"title": "微信形式的输入栏与示例发送", "description": "文字输入左侧增加语音按钮，右侧增加图片按钮，保留文字发送。点击语音或图片直接发送对应示例消息，无需授权麦克风或选择真实文件。", "fields": "assistantVoiceButton、assistantImageButton；sessions[].messages[]新增demoChatVoice/demoChatImage；每条有id、at，语音含text，图片含src。", "logic": "语音示例显示8秒气泡及识别文字；图片示例显示处方缩略图。发送仅写入会话，不立即新增申请或病程。保留原文字输入和流程内上传能力；正在回复/保存时提示等待，避免重复交错处理。示例语音播放只展示动态效果，不调用录音或识别服务。 输入栏以语音、文字、图片、发送四列独立布局；发送按钮清除旧负边距，320px及390px下不覆盖图片按钮。"}, {"title": "图片收到后的三种操作", "description": "图片后仅展示文案：我已经收到了您的图片，需要我帮你做些什么么。给出记录病程并且发起新的患者福利申请、仅记录病程、仅申请理赔三个按钮；移除原需要发起新的创新支付吗标题及二选一按钮。", "fields": "demoMediaIntent.intent=payment；sourceMessageId；imageRecordId=assistant-image-消息ID；imageRecorded/imageNativeSaved；imageApplicationStatus/Kind；三种choice=record-and-benefit/record-only/claim-only。", "logic": "仅记录病程：保存原图并使用现有Demo提取逻辑生成时间和描述，写主病程后同步助手病历夹；不创建申请。组合选项：先完成同一条图片病程保存，再校验资格与审核中限制并打开患者福利申请页；记录成功但申请受限时明确反馈已记录及受限原因，不回滚病程。仅申请理赔：不新建病程，进入后报销申请页，仅提供reimburse方式并要求发票，图片预填为处方示例。\n同一图片消息使用稳定ID；刷新、重试或改选组合选项复用已保存病程，不重复新增，不覆盖人工修改。进入申请页不等于提交，提交前仍校验材料、同意项和数量。保存失败保留输入可重试；主病程已存而镜像失败时提示重试同步。三个选项执行期间禁用重复点击，保存后仅记录按钮禁用，其余申请入口可继续使用。"}, {"title": "语音发送后的病程确认", "description": "语音消息后在聊天内询问是否将刚刚的信息记录到病程；确认后新增一条可回看的病程，拒绝不新增业务记录。", "fields": "demoMediaIntent.intent=journey；recordId=assistant-voice-消息ID；status=pending/saving/saved/declined；nativeSaved、error；原始语音示例文字和at固定保存。", "logic": "确认时以消息ID生成稳定病程ID，调用宿主saveVoiceRecord；保留原文，并沿用既有提取逻辑生成时间和描述。主记录成功后同步助手病历夹镜像。重复点击、刷新或重试按相同ID去重，不覆盖已人工编辑记录；成功卡片提供查看病程。主记录保存失败不新增，展示错误并允许重试；主记录已存但镜像失败时提示重试同步，不重复建档。暂不需要不写入病程或猝倒/用药统计。"}, {"title": "底部弹窗复用首页病程模块", "description": "点击记录病程从底部拉起弹窗，内部呈现首页同一病程模块：选择语音/图片、整理加载、原始资料、时间和描述核对及保存。", "fields": "assistantWorkflowDialog(mode=journey)；assistantJourneyFrame；assistantJourney=1嵌入参数；mianbao-journey-saved/close消息；mianbaoJourneyHost桥接。", "logic": "仅在助手触发的嵌入模式隐藏重复的说明栏、手机状态栏及主导航；普通首页与其他页面布局不变。接收消息必须匹配同源及当前嵌入窗口。顶部返回/关闭回到原会话，未完成资料沿用原草稿保存；保存后刷新宿主病程数据并同步助手病历夹，展示已保存卡片。查看或修改同一记录使用caseId回填原记录，不重新提取、不重复新增。"}, {"title": "底部弹窗复用首页用药记录入口", "description": "点击会话中的用药记录或记录一次用药按钮，从底部打开用药记录弹窗，内部直接展示首页同名入口当前对应的功能。", "fields": "assistantWorkflowDialog.mode=medication；assistantMedication=1；宿主路由medReminder；settings.medTime、notificationEnabled；mianbao-medication-saved事件。", "logic": "当前首页用药记录入口指向medReminder，本次复用其每日提醒时间和通知开关及保存能力，不重新制作另一套表单。打开读取同一settings；关闭未保存不写入，保存后关闭弹窗并同步宿主设置，避免后续病程保存覆盖新设置。嵌入模式隐藏重复说明和主导航，主页面仍停留在眠宝帮您。首页原入口、页面与其他业务数据保持原样；既有用药历史仍保留在病历夹中。"}];

