PAGE_MODULES.ai = [{"title": "眠宝欢迎与咨询", "description": "保留眠宝帮您标题、发作性睡病之家品牌副标、眠宝形象和问候；欢迎卡片移除发作性睡病之家 · 眠宝陪伴这一行。保留热门问题与自由咨询。", "fields": "服务独立状态 mianbao-integrated-service-v1；sessions[]、messages[]。", "logic": "欢迎区仅展示眠宝形象与介绍，点击问问眠宝进入咨询；不展示或写入每日状态记录。会话超过 3 天未互动新建，历史保留近 12 个月；AI 为本地规则匹配，医学与政策内容待正式审核。该模块数据不改写首页、专病管理、权益中心与我的现有记录。 应用名是发作性睡病之家，眠宝是陪伴角色，眠宝帮您是助手功能名；不更名路由、存储键或福利计划。"}, {"title": "创新支付、入组与援助申请", "description": "展示入组、福利订单和直付/后报销进度；在会话中逐步完善资料、上传材料、核对提交，支持暂停、恢复、重新填写及驳回补件。 首屏创新支付入口卡片增加状态tag，与会话上方创新支付快捷入口使用同一状态汇总。 点击创新支付首屏卡片或会话快捷入口，进入独立二级页面查看进度与申请详情，移除原会话内展开形式。", "fields": "enrollment、type、code、patient、orders[]、aidDrafts 与会话 careFlows；材料图片本地保存。 assistantPaymentMeta()由state.enrollment/type/code计算tag，两个入口不额外保存标签。", "logic": "保留源模块的状态字典与订单过滤：20 区分药房审核阶段、21 过滤；后报销需处方与发票，直付含用药数量。申请提交为本地流程，未接保险/审核/理赔接口；不改变首页患者福利的状态。 tag沿用当前助手既有入组/审核/通过/完成状态映射，申请提交后随状态重绘；本次不改变首页患者福利的状态映射。 入口进入独立页面不新增聊天消息；返回保留当前会话和输入。首屏标签和快捷入口仍共用assistantPaymentMeta()。"}, {"title": "记录病程入口与既有记录", "description": "助手首页病历夹卡片改为记录病程，与会话上方记录病程按钮打开同一个底部病程模块。既有病历夹及用药历史继续保留，通过已有记录链接回看。", "fields": "feature.action=recordJourney；openNativeJourney()；assistantWorkflowDialog.mode=journey；assistantJourneyFrame；原records动作保留。", "logic": "两个记录病程入口复用相同函数、页面、草稿与主病程数据；点击仅打开病程录入，不生成新记录，核对保存后才写入。关闭遵循原草稿保存逻辑。既有记录查看链接不随首页入口改名失效；用药弹窗逻辑不变。"}, {"title": "健康科普", "description": "先在聊天中展示三篇推荐文章；查看更多展开六篇文章及分类，支持全文阅读、收起与展开。", "fields": "源模块 articles[]、articleFilter、articleId 与消息 kind=articles/appPanel。", "logic": "所有文章操作保持在眠宝会话内；内容为记录与资料整理说明，正式医学内容和发布审核接口待接入。"}, {"title": "客服与我的服务", "description": "真人客服、联系客服及回复中的客服入口展示企业微信二维码卡片；头像仍展开患者资料、历史会话和福利关爱记录。", "fields": "patient、sessions[]、orders[]；历史会话分页；申请人姓名打码。reports[] 仅保留旧数据兼容，不新增事件记录。 客服面板panelType=customerService；示意资源assets/wecom-qr-placeholder.svg。", "logic": "在聊天中展示眠宝、企业微信客服标题和二维码示意图；按用户确认，本期只使用示意图片，无真实企业微信账号或跳转。重复点击收起上一张同类型卡片并展开当前卡片；保存到会话后刷新可回看。创新支付独立页面内调用客服时沿用该页面容器。签约药房联系功能保持原行为。"}, {"title": "会话快捷操作", "description": "会话开始后显示横向创新支付、记录病程、用药记录、真人客服按钮；记录病程与用药记录均打开底部复用模块。移除顶部状态按钮。", "fields": "activeSession、view、conversationActions；入组/支付/订单状态控件。", "logic": "图片或语音示例发送均可发起会话并显示快捷服务。顶部不再提供患者手动切换服务状态的按钮；保留既有申请状态和业务数据。记录病程进入journey嵌入模式；用药记录进入首页同一入口当前对应的medReminder嵌入模式，其余服务入口保持原逻辑。"}, {"title": "左侧说明工具：清空聊天记录", "description": "各页面左侧说明下方均展示清空聊天记录按钮，说明编辑状态也可使用。点击清空眠宝帮您中的历史会话和当前对话，回到助手欢迎状态。", "fields": "mianbao-integrated-service-v1.sessions[]；activeSession、typing、replyTimer；chatHistoryClearing；子模块window.clearMianbaoChatHistory()。", "logic": "全局按钮调用眠宝已有会话清理逻辑，不改变当前主页面路由或左侧/右侧未保存内容。若助手未打开，临时加载同一服务执行清理，完成后移除临时载体；助手已打开时同步清空界面并关闭历史详情。清除等待中的回复及输入，不重新生成示例历史；刷新或再次进入仍为空。\n已保存的病程、用药、图片语音附件、患者资料及福利订单不清除；援助申请草稿沿用既有保留逻辑。重复点击期间禁用按钮；保存失败恢复原会话状态并提示，不显示虚假成功。此按钮属于左侧说明工具，不加入患者端功能导航。"}, {"title": "微信形式的输入栏与示例发送", "description": "文字输入左侧增加语音按钮，右侧增加图片按钮，保留文字发送。点击语音或图片直接发送对应示例消息，无需授权麦克风或选择真实文件。", "fields": "assistantVoiceButton、assistantImageButton；sessions[].messages[]新增demoChatVoice/demoChatImage；每条有id、at，语音含text，图片含src。", "logic": "语音示例显示8秒气泡及识别文字；图片示例显示处方缩略图。发送仅写入会话，不立即新增申请或病程。保留原文字输入和流程内上传能力；正在回复/保存时提示等待，避免重复交错处理。示例语音播放只展示动态效果，不调用录音或识别服务。 输入栏以语音、文字、图片、发送四列独立布局；发送按钮清除旧负边距，320px及390px下不覆盖图片按钮。"}, {"title": "图片收到后的三种操作", "description": "图片后仅展示文案：我已经收到了您的图片，需要我帮你做些什么么。给出记录病程并且发起新的患者福利申请、仅记录病程、仅申请理赔三个按钮；移除原需要发起新的创新支付吗标题及二选一按钮。", "fields": "demoMediaIntent.intent=payment；sourceMessageId；imageRecordId=assistant-image-消息ID；imageRecorded/imageNativeSaved；imageApplicationStatus/Kind；三种choice=record-and-benefit/record-only/claim-only。", "logic": "仅记录病程：保存原图并使用现有Demo提取逻辑生成时间和描述，写主病程后同步助手病历夹；不创建申请。组合选项：先完成同一条图片病程保存，再校验资格与审核中限制并打开患者福利申请页；记录成功但申请受限时明确反馈已记录及受限原因，不回滚病程。仅申请理赔：不新建病程，进入后报销申请页，仅提供reimburse方式并要求发票，图片预填为处方示例。\n同一图片消息使用稳定ID；刷新、重试或改选组合选项复用已保存病程，不重复新增，不覆盖人工修改。进入申请页不等于提交，提交前仍校验材料、同意项和数量。保存失败保留输入可重试；主病程已存而镜像失败时提示重试同步。三个选项执行期间禁用重复点击，保存后仅记录按钮禁用，其余申请入口可继续使用。"}, {"title": "语音发送后的病程确认", "description": "语音消息后在聊天内询问是否将刚刚的信息记录到病程；确认后新增一条可回看的病程，拒绝不新增业务记录。", "fields": "demoMediaIntent.intent=journey；recordId=assistant-voice-消息ID；status=pending/saving/saved/declined；nativeSaved、error；原始语音示例文字和at固定保存。", "logic": "确认时以消息ID生成稳定病程ID，调用宿主saveVoiceRecord；保留原文，并沿用既有提取逻辑生成时间和描述。主记录成功后同步助手病历夹镜像。重复点击、刷新或重试按相同ID去重，不覆盖已人工编辑记录；成功卡片提供查看病程。主记录保存失败不新增，展示错误并允许重试；主记录已存但镜像失败时提示重试同步，不重复建档。暂不需要不写入病程或猝倒/用药统计。"}, {"title": "底部弹窗复用首页病程模块", "description": "点击记录病程从底部拉起弹窗，内部呈现首页同一病程模块：选择语音/图片、整理加载、原始资料、时间和描述核对及保存。 助手首页记录病程卡片与会话快捷按钮均复用此弹窗。", "fields": "assistantWorkflowDialog(mode=journey)；assistantJourneyFrame；assistantJourney=1嵌入参数；mianbao-journey-saved/close消息；mianbaoJourneyHost桥接。", "logic": "仅在助手触发的嵌入模式隐藏重复的说明栏、手机状态栏及主导航；普通首页与其他页面布局不变。接收消息必须匹配同源及当前嵌入窗口。顶部返回/关闭回到原会话，未完成资料沿用原草稿保存；保存后刷新宿主病程数据并同步助手病历夹，展示已保存卡片。查看或修改同一记录使用caseId回填原记录，不重新提取、不重复新增。"}, {"title": "底部弹窗复用首页用药记录入口", "description": "点击会话中的用药记录或记录一次用药按钮，从底部打开用药记录弹窗，内部直接展示首页同名入口当前对应的功能。", "fields": "assistantWorkflowDialog.mode=medication；assistantMedication=1；宿主路由medReminder；settings.medTime、notificationEnabled；mianbao-medication-saved事件。", "logic": "当前首页用药记录入口指向medReminder，本次复用其每日提醒时间和通知开关及保存能力，不重新制作另一套表单。打开读取同一settings；关闭未保存不写入，保存后关闭弹窗并同步宿主设置，避免后续病程保存覆盖新设置。嵌入模式隐藏重复说明和主导航，主页面仍停留在眠宝帮您。首页原入口、页面与其他业务数据保持原样；既有用药历史仍保留在病历夹中。"}, {"title": "创新支付独立页面与返回逻辑", "description": "创新支付卡片、会话快捷入口及申请详情入口统一进入新的二级页面。顶部显示页面标题和返回按钮，隐藏聊天输入与首页底部功能栏。", "fields": "paymentPageActive；paymentPageStack[{title,body,footer,kind,orderId,scrollTop}]；selectedOrderId；pendingDraft；mianbao-payment-page-state.open。", "logic": "已入组有申请：进入最新可见申请，保留订单切换、状态、审批节点、材料与申请按钮；无申请：显示申请指引；未入组/待补充/被驳回：进入对应资料页；入组审核中：展示进度页。普通卡片入口的申请、重新上传、提交成功、查看材料均在独立页面内完成；保留原申请校验和审核中禁用规则。独立页面不作为消息写入历史、不自动新建会话或订单。返回材料回到对应订单；根页面返回原助手会话，重新展示快捷入口、输入框与底部导航。申请成功页移除可重复提交的旧表单返回项；再查看申请展示最新审核状态。图片消息三选项继续沿用已实现的申请弹窗；病程/用药弹窗保持原形式。"}, {"title": "每次问答后的猜你想问", "description": "每次自由咨询得到回复后，在该条回复底部展示三条可点击的猜你想问。覆盖疾病、用药、福利及超范围问题。", "fields": "bot.suggestedQuestions:string[3]；questionSuggestions(text)；questionSuggestionsMarkup()；data-question。", "logic": "按本次问题关键词选择疾病/用药/福利的问题集合，去重并排除与原问题完全相同的条目，再补足三条。推荐列表附着回复保存到会话，刷新和历史回看保持一致；每次重绘不追加重复消息。点击推荐复用文字发送、等待回复和保存流程，并为新回复生成三条推荐。原首页三个热门问题保留；图片/语音确认卡和申请资料填写不冒充自由咨询，不额外插入问答推荐。清空聊天一并清除回复及其推荐。"}];

